local function moveToWaypoint(root, humanoid, point, speed, dt)
    local offset = Vector3.new(point.X, root.Position.Y, point.Z) - root.Position
    local horizontal = Vector3.new(offset.X, 0, offset.Z)
    if horizontal.Magnitude <= 1 then
        return true
    end
    local direction = horizontal.Unit
    local currentSpeed = math.max(tonumber(speed) or tonumber(fn38()) or 60, 0)
    local frameTime = math.max(tonumber(dt) or (1 / 60), 1 / 240)
    currentSpeed = math.min(currentSpeed, horizontal.Magnitude / frameTime)
    pcall(function() humanoid:Move(direction, false) end)
    local velocity = root.AssemblyLinearVelocity
    root.AssemblyLinearVelocity = Vector3.new(direction.X * currentSpeed, velocity.Y, direction.Z * currentSpeed)
    return false
end

local function startAutoLeft()
    if tbl31.R then
        stopAutoRight()
    end
    if leftConnection then
        leftConnection:Disconnect()
        leftConnection = nil
    end
    leftPhase, tbl31.L = 1, true
    _G._AdaptAutoPathActive = true
    setPathSpeedMode(false)
    refreshAutoPathUI("L", true)
    leftConnection = RunService.Heartbeat:Connect(function(dt)
        if not tbl31.L then return end
        if not _G._AdaptAutoPathMatchSpeed and (tbl22.family ~= "normal" or tbl22.carry) then
            setPathSpeedMode(false)
