-- NTXA's async waypoint pathfinding with direct-line fallback.
local function route(key, rootPos, goal)
 local now = os.clock()
 local st = nPath.caches[key]
 if not st then
   st = {goal = goal, pts = nil, idx = 2, last = -math.huge, busy = false}
   nPath.caches[key] = st
 end
 if not st.busy and (not st.pts or now - st.last > 1.25) then
   st.busy, st.last, st.goal = true, now, goal
   local current, generation, origin = st, nPath.gen, rootPos
   task.spawn(function()
     local ok, path = pcall(function()
       local svc = game:GetService("PathfindingService")
       local obj = svc:CreatePath({AgentRadius=2.5, AgentHeight=5, AgentCanJump=true, WaypointSpacing=6})
       obj:ComputeAsync(origin, goal)
       return obj
     end)
     if nPath.gen ~= generation or nPath.caches[key] ~= current then return end
     current.busy = false
     if ok and path and path.Status == Enum.PathStatus.Success then
       current.pts, current.idx = path:GetWaypoints(), 2
     else current.pts = nil end
   end)
 end
 if st.pts then
   while st.idx <= #st.pts do
     local pt = st.pts[st.idx].Position
     local delta = Vector3.new(pt.X-rootPos.X, 0, pt.Z-rootPos.Z)
     if delta.Magnitude > 4 then return delta.Unit end
     st.idx += 1
   end
 end
 return nil
end
