								-- Upgraded Solo TP Bat V1 & V2 Engine (PhysicsRepRootPart + Anti-Desync Velocity Tracking + 300x Vortex/Body-Spam V2)
								local snowTPBatEnabled = false
								local snowTPBatConnection = nil
								local snowTPBatRenderConn = nil
								local snowAntiDieConnections = {}
								local tpBatVelHist = setmetatable({}, { __mode = "k" })
								local tpBatLastSwing = 0
								local tpBatLastPingCheck = 0
								local tpBatPing = 0.08
								local tpBatSpinAngle = 0
								local tpBatOrbitAngle = 0
								local tpBatStepPhase = 0

								local function disconnectAntiDie()
								    for _, conn in ipairs(snowAntiDieConnections) do
								        pcall(function() conn:Disconnect() end)
								    end
								    snowAntiDieConnections = {}
								end
								
								local function hookAntiDie(character)
								    disconnectAntiDie()
								    if not snowTPBatEnabled or not character then return end
								
								    local humanoid = character:FindFirstChildOfClass("Humanoid")
								    if not humanoid then return end
								
								    pcall(function()
								        humanoid.BreakJointsOnDeath = false
								        humanoid:SetStateEnabled(Enum.HumanoidStateType.Dead, false)
								        humanoid:SetStateEnabled(Enum.HumanoidStateType.Dying, false)
								    end)
								
								    table.insert(snowAntiDieConnections, humanoid:GetPropertyChangedSignal("Health"):Connect(function()
								        if snowTPBatEnabled and humanoid.Parent and humanoid.Health <= 25 then
								            pcall(function()
								                humanoid.Health = humanoid.MaxHealth
								                humanoid:ChangeState(Enum.HumanoidStateType.Running)
								            end)
								        end
								    end))
								end
								
								local function findBat()
								    local character = localPlayer.Character
								    if not character then return nil end
								
								    for _, child in ipairs(character:GetChildren()) do
								        if child:IsA("Tool") then
								            local n = child.Name:lower()
								            if n:find("bat") or n:find("slap") then
								                return child
								            end
								        end
								    end
								
								    local backpack = localPlayer:FindFirstChildOfClass("Backpack")
								    if backpack then
								        for _, child in ipairs(backpack:GetChildren()) do
								            if child:IsA("Tool") then
								                local n = child.Name:lower()
								                if n:find("bat") or n:find("slap") then
								                    local humanoid = character:FindFirstChildOfClass("Humanoid")
								                    if humanoid then
								                        pcall(function() humanoid:EquipTool(child) end)
								                    end
								                    return child
								                end
								            end
								        end
								    end
								
								    return nil
								end
								
								local function nearestPlayerTarget(root)
								    if not root then return nil, math.huge end
								    local best, bestD = nil, math.huge
								
								    for _, player in ipairs(Players:GetPlayers()) do
								        if player ~= localPlayer and player.Character then
								            local otherRoot = player.Character:FindFirstChild("HumanoidRootPart")
								            local otherHum  = player.Character:FindFirstChildOfClass("Humanoid")
								            if otherRoot and otherHum and otherHum.Health > 0 then
								                local tPos = otherRoot.Position
								                if _G.AdaptNTXAAntiVoid and _G.AdaptNTXAAntiVoid.posForPart then
								                    tPos = _G.AdaptNTXAAntiVoid.posForPart(otherRoot, tPos) or tPos
								                end
								                if tPos.Y > -25 then
								                    local d = (root.Position - tPos).Magnitude
								                    if d < bestD then
								                        bestD = d
								                        best = player
								                    end
								                end
								            end
								        end
								    end
								
								    return best, bestD
								end

								local function trackEnemyCleanVel(targetRoot, rawPos)
								    local now = os.clock()
								    local h = tpBatVelHist[targetRoot]
								    local vel = Vector3.zero
								    local accel = Vector3.zero
								    if h then
								        local dt = now - h.t
								        if dt > 0.003 and dt < 0.45 then
								            local obs = (rawPos - h.p) / dt
								            local flatObs = Vector3.new(obs.X, 0, obs.Z)
								            -- Filter out Anti-Bat velocity desync spikes (>115 studs/s)
								            if flatObs.Magnitude > 115 then
								                flatObs = flatObs.Unit * 85
								            end
								            local cleanObs = Vector3.new(flatObs.X, math.clamp(obs.Y, -75, 75), flatObs.Z)
								            local blend = math.clamp(dt * 16, 0.25, 0.85)
								            vel = (h.v or Vector3.zero):Lerp(cleanObs, blend)
								            accel = (h.a or Vector3.zero):Lerp((vel - (h.v or Vector3.zero)) / dt, 0.35)
								        else
								            vel = h.v or Vector3.zero
								            accel = h.a or Vector3.zero
								        end
								    end
								    tpBatVelHist[targetRoot] = { t = now, p = rawPos, v = vel, a = accel }
								    return vel, accel
								end

								local function safeSnap(root, pos, lookAt)
								    local flatLook = Vector3.new(lookAt.X - pos.X, 0, lookAt.Z - pos.Z)
								    if flatLook.Magnitude > 0.05 then
								        root.CFrame = CFrame.lookAt(pos, Vector3.new(lookAt.X, pos.Y, lookAt.Z))
								    else
								        root.CFrame = CFrame.new(pos)
								    end
								    root.AssemblyLinearVelocity = Vector3.zero
								    root.AssemblyAngularVelocity = Vector3.zero
								end
								
								local function strikeEnemy(bat, enemyChar, targetRoot, minInterval)
								    local now = os.clock()
								    if now - tpBatLastSwing < (minInterval or 0.03) then return end
								    tpBatLastSwing = now
								
								    pcall(function()
								        if not bat then bat = findBat() end
								        if not bat then return end
								        bat:Activate()
								        local remote = bat:FindFirstChildWhichIsA("RemoteEvent", true)
								        if remote then
								            remote:FireServer()
								        end
								        if type(firetouchinterest) == "function" then
								            local handle = bat:FindFirstChild("Handle") or bat:FindFirstChildWhichIsA("BasePart")
								            if handle and targetRoot then
								                firetouchinterest(handle, targetRoot, 0)
								                firetouchinterest(handle, targetRoot, 1)
								                if enemyChar then
								                    for _, partName in ipairs({"UpperTorso", "Torso", "Head", "LeftLowerArm", "RightLowerArm"}) do
								                        local bp = enemyChar:FindFirstChild(partName)
								                        if bp and bp:IsA("BasePart") then
								                            firetouchinterest(handle, bp, 0)
								                            firetouchinterest(handle, bp, 1)
								                        end
								                    end
								                end
								            end
								        end
								    end)
								end
								
								local function tpBatTick(dt)
								    if not snowTPBatEnabled then return end
								    dt = (type(dt) == "number" and dt > 0 and dt < 0.1) and dt or (1 / 60)
								
								    local character = localPlayer.Character
								    if not character then return end
								
								    local root     = character:FindFirstChild("HumanoidRootPart")
								    local humanoid = character:FindFirstChildOfClass("Humanoid")
								    if not root or not humanoid or humanoid.Health <= 0 then return end

								    if not _G._SoloNTXAInstantResetBusy then
								        pcall(function()
								            humanoid.BreakJointsOnDeath = false
								            humanoid:SetStateEnabled(Enum.HumanoidStateType.Dead, false)
								        end)
								    end
								    humanoid.AutoRotate = false
								
								    local bat = findBat()
								    if bat and bat.Parent ~= character then
								        pcall(function() humanoid:EquipTool(bat) end)
								    end
								
								    local target = nearestPlayerTarget(root)
								    if not target or not target.Character then return end
								
								    local enemyChar = target.Character
								    local targetRoot = enemyChar:FindFirstChild("HumanoidRootPart")
								    if not targetRoot then return end

								    local rawPos = targetRoot.Position
								    local isGhost = false
								    if _G.AdaptNTXAAntiVoid and _G.AdaptNTXAAntiVoid.posForPart then
								        local gp, gFlag = _G.AdaptNTXAAntiVoid.posForPart(targetRoot, rawPos)
								        if gp then rawPos = gp; isGhost = gFlag == true end
								    end

								    if _G._AdaptVoltHiddenPropertyDisabled then
								        pcall(_G._AdaptVoltHiddenPropertyDisabled, root, "PhysicsRepRootPart", isGhost and nil or targetRoot)
								    end

								    local now = os.clock()
								    if now - tpBatLastPingCheck >= 0.4 then
								        tpBatLastPingCheck = now
								        pcall(function() tpBatPing = math.clamp(localPlayer:GetNetworkPing(), 0.02, 0.22) end)
								    end

								    local cleanVel, cleanAccel = Vector3.zero, Vector3.zero
								    if not isGhost then
								        cleanVel, cleanAccel = trackEnemyCleanVel(targetRoot, rawPos)
								    end
								    local flatVel = Vector3.new(cleanVel.X, 0, cleanVel.Z)

								    local isV2 = (_G._AdaptTPBatVersion ~= "V1")
								    if not isV2 then
								        -- ============================================================
								        -- TP BAT V1 (UPGRADED): Predictive Anti-Desync Chest Lock + Multi-Angle Strike
								        -- ============================================================
								        local lead = math.clamp(tpBatPing + 0.045, 0.04, 0.14)
								        local predPos = rawPos + cleanVel * lead
								        local center = predPos + Vector3.new(0, 0.45, 0)
								        tpBatStepPhase = (tpBatStepPhase + 1) % 4
								        local lookVec = targetRoot.CFrame.LookVector
								        local rightVec = targetRoot.CFrame.RightVector
								        local offset = Vector3.zero
								        if flatVel.Magnitude > 1 then
								            offset = flatVel.Unit * 0.45
								        elseif tpBatStepPhase == 1 then
								            offset = lookVec * 0.35
								        elseif tpBatStepPhase == 2 then
								            offset = -lookVec * 0.35
								        elseif tpBatStepPhase == 3 then
								            offset = rightVec * 0.35
								        end
								        local snapPos = center + offset
								        safeSnap(root, snapPos, rawPos + lookVec * 2)
								        strikeEnemy(bat, enemyChar, targetRoot, 0.03)
								    else
								        -- ============================================================
								        -- TP BAT V2 (ULTRA APEX 300x VORTEX + BODY-SPAM SATURATION)
								        -- ============================================================
								        local lead = math.clamp(tpBatPing + 0.065, 0.05, 0.18)
								        local predPos = rawPos + cleanVel * lead + cleanAccel * (0.15 * lead * lead)
								        local center = predPos + Vector3.new(0, 0.45, 0)
								        local look = targetRoot.CFrame.LookVector
								        local right = targetRoot.CFrame.RightVector
								        local anchor = center
								        if flatVel.Magnitude > 0.5 then
								            anchor = center + flatVel.Unit * 0.55
								        end

								        tpBatOrbitAngle = (tpBatOrbitAngle + 60 * dt * 5) % (math.pi * 200)
								        tpBatSpinAngle = (tpBatSpinAngle + 48 * dt * 4.4) % (math.pi * 200)
								        local ang = tpBatOrbitAngle
								        local spin = tpBatSpinAngle
								        local cs, sn = math.cos(spin), math.sin(spin)
								        local N = 300
								        for i = 1, N do
								            if i <= 180 then
								                -- High-density 3D vortex spiral around predicted anchor
								                local t = i / 180
								                local radius = 0.25 + 2.15 * math.abs(math.sin(t * math.pi * 3))
								                local a = ang + t * 12
								                local p = anchor
								                    + right * (math.cos(a) * radius)
								                    + look  * (math.sin(a) * radius)
								                    + Vector3.new(0, math.sin(a * 1.5) * 0.15, 0)
								                safeSnap(root, p, anchor)
								            else
								                -- Tight body-spam saturation matrix directly through enemy torso
								                local jx = ((i % 5) - 2) * 0.06
								                local jz = ((i % 7) - 3) * 0.05
								                local jy = ((i % 3) - 1) * 0.03
								                local ox = jx * cs - jz * sn
								                local oz = jx * sn + jz * cs
								                local p = anchor + right * ox + look * (0.12 + oz) + Vector3.new(0, jy, 0)
								                safeSnap(root, p, anchor)
								            end
								        end
								        local faceTarget = anchor + Vector3.new(math.sin(ang) * 0.35, 0, math.cos(ang) * 0.35)
								        safeSnap(root, anchor + Vector3.new(0, 0.15, 0), faceTarget)
								        strikeEnemy(bat, enemyChar, targetRoot, 0.015)
								    end
								
								    local camera = workspace.CurrentCamera
								    if camera then
								        pcall(function()
								            camera.CFrame = CFrame.new(camera.CFrame.Position, rawPos)
								        end)
								    end
								
								    pcall(function()
								        for _, descendant in ipairs(character:GetDescendants()) do
								            if descendant:IsA("BasePart") then
								                descendant.CanCollide = false
								            end
								        end
								    end)
								end
								
								local function snowSetEnabled(value)
								    snowTPBatEnabled = value == true
								
								    if snowTPBatEnabled then
								        hookAntiDie(localPlayer.Character)
								        if snowTPBatConnection then
								            snowTPBatConnection:Disconnect()
								            snowTPBatConnection = nil
								        end
								        if snowTPBatRenderConn then
								            snowTPBatRenderConn:Disconnect()
								            snowTPBatRenderConn = nil
								        end
								        snowTPBatRenderConn = RunService.RenderStepped:Connect(tpBatTick)
								        snowTPBatConnection = RunService.Heartbeat:Connect(tpBatTick)
								    else
								        if snowTPBatRenderConn then
								            snowTPBatRenderConn:Disconnect()
								            snowTPBatRenderConn = nil
								        end
								        if snowTPBatConnection then
								            snowTPBatConnection:Disconnect()
								            snowTPBatConnection = nil
								        end
								        disconnectAntiDie()
								        table.clear(tpBatVelHist)
								
								        local char = localPlayer.Character
								        local root = char and char:FindFirstChild("HumanoidRootPart")
								        local hum = char and char:FindFirstChildOfClass("Humanoid")
								        if hum then
								            pcall(function() hum.AutoRotate = true end)
								        end
								        if root then
								            if _G._AdaptVoltHiddenPropertyDisabled then
								                pcall(_G._AdaptVoltHiddenPropertyDisabled, root, "PhysicsRepRootPart", nil)
								            end
								            root.AssemblyLinearVelocity = Vector3.zero
								            root.AssemblyAngularVelocity = Vector3.zero
								        end
								    end
								end
								
								localPlayer.CharacterAdded:Connect(function(character)
								    if snowTPBatEnabled then
								        task.wait(0.1)
								        hookAntiDie(character)
								    end
								end)
								
