end

_AdaptMain()



-- BEGIN NTXA BAT AIMBOT PORT (V2/V3/V4 NORMAL + BYPASS)
-- Self-contained adaptation for Adapt. Does not load NTXA's UI or other systems.
do
  local Players = game:GetService("Players")
  local RunService = game:GetService("RunService")
  local LP = Players.LocalPlayer
  local ctl = {version="V2",mode="NORMAL",enabled=false,connection=nil,character=nil,
    target=nil,lastPos=nil,lastTime=nil,vel=Vector3.zero,smooth=Vector3.zero,
    accel=Vector3.zero,lastSwing=0,lastPing=0,ping=0.1,turnAt=0,
    prevDir=nil,airTime=0,velocityWritten=nil,angularWritten=nil,gui=nil}
  local profiles = {V2={speed=58,lead=0.14,lift=2.5,turn=42,response=.8,interval=.08},
    V3={speed=64,lead=0.14,lift=2.5,turn=42,response=.8,interval=.08},
    V4={speed=72,lead=0.24,lift=2.2,turn=50,response=.90,interval=.05},
    V5={speed=58,lead=0.20,lift=1.5,turn=52,response=.95,interval=.04}}
  local function safeVec3(v)
    if not v or v.X ~= v.X or v.Y ~= v.Y or v.Z ~= v.Z then
      return Vector3.zero
    end
    if math.abs(v.X) > 1e4 or math.abs(v.Y) > 1e4 or math.abs(v.Z) > 1e4 then
      return Vector3.zero
    end
    return v
  end
  local function resetPrediction()
    ctl.target=nil; ctl.lastPos=nil; ctl.lastTime=nil
    ctl.vel=Vector3.zero; ctl.smooth=Vector3.zero; ctl.accel=Vector3.zero
    ctl.prevDir=nil; ctl.airTime=0; ctl.lastSwing=0; ctl.turnAt=0
  end
  local function isMine(root)
    return root and ctl.character and root.Parent==ctl.character
  end
  local function release()
    local c=ctl.character
    local r=c and c:FindFirstChild("HumanoidRootPart")
    local h=c and c:FindFirstChildOfClass("Humanoid")
    if isMine(r) then
      if ctl.velocityWritten and (r.AssemblyLinearVelocity-ctl.velocityWritten).Magnitude<4 then
        r.AssemblyLinearVelocity=Vector3.zero
      end
      if ctl.angularWritten and (r.AssemblyAngularVelocity-ctl.angularWritten).Magnitude<4 then
        r.AssemblyAngularVelocity=Vector3.zero
      end
      if h then h.AutoRotate=true end
    end
    ctl.velocityWritten=nil; ctl.angularWritten=nil
    local v1StillOn = (_G._AdaptSafeModeActionActive and _G._AdaptSafeModeActionActive("aimbot") == true) or false
    if not v1StillOn and _G._SoloSetAimbotMoveLock then
      _G._SoloSetAimbotMoveLock(false)
    end
  end
  local function selectTarget(root)
    local best,d=nil,math.huge
    for _,p in ipairs(Players:GetPlayers()) do
      if p~=LP then
        local c=p.Character
        local r=c and c:FindFirstChild("HumanoidRootPart")
        local h=c and c:FindFirstChildOfClass("Humanoid")
        if r and h and h.Health>0 and r.Position.Y > -25 then
          local nd=(r.Position-root.Position).Magnitude
          if nd<d then d=nd;best=r end
        end
      end
    end
    return best,d
  end
  local function findBat(c)
    local function accepted(t)
      if not t:IsA("Tool") then return false end
      local n=t.Name:lower()
      return n:find("bat",1,true)~=nil or n:find("slap",1,true)~=nil
    end
    for _,t in ipairs(c:GetChildren()) do if accepted(t) then return t end end
    local bag=LP:FindFirstChildOfClass("Backpack")
    if bag then for _,t in ipairs(bag:GetChildren()) do if accepted(t) then return t end end end
  end
  local function step(dt)
    if not ctl.enabled then return end
    local c=LP.Character
    if ctl.character~=c then release();ctl.character=c;resetPrediction() end
    local r=c and c:FindFirstChild("HumanoidRootPart")
    local h=c and c:FindFirstChildOfClass("Humanoid")
    if not r or not h or h.Health<=0 then resetPrediction();return end
    if _G._SoloSetAimbotMoveLock then _G._SoloSetAimbotMoveLock(true) end
    pcall(function() h:Move(Vector3.zero, false) end)
    if not _G._SoloNTXAInstantResetBusy then
      pcall(function()
        h.BreakJointsOnDeath = false
        h:SetStateEnabled(Enum.HumanoidStateType.Dead, false)
      end)
    end
    local target,dist=selectTarget(r)
    if not target then
      ctl.velocityWritten=nil; ctl.angularWritten=nil
      r.AssemblyLinearVelocity=Vector3.new(0, r.AssemblyLinearVelocity.Y, 0)
      r.AssemblyAngularVelocity=Vector3.zero
      resetPrediction()
      return
    end
    if target~=ctl.target then resetPrediction();ctl.target=target end
    local p=profiles[ctl.version] or profiles.V5
    local pos=target.Position
    if _G.AdaptNTXAAntiVoid and _G.AdaptNTXAAntiVoid.posForPart then
      pos=_G.AdaptNTXAAntiVoid.posForPart(target, pos) or pos
    end
    local now=os.clock(); local interval=math.max(dt,1/240)
    local aim=pos
    local speed=math.clamp(tonumber(_G._AdaptAimbotSpeed) or p.speed or 58, 1, 200)
    if ctl.version=="V5" then
      -- V5: Ported Normal & Bypass Aimbot from Kayz Duel source
      ctl.lastPos=pos; ctl.lastTime=now
      h.AutoRotate=false
      local myPos = r.Position
      local targetVel = safeVec3(target.AssemblyLinearVelocity)
      local desired = Vector3.zero
      local angular = Vector3.zero
      local lerpAlpha = 0.85
      local swingRange = 5.5
      local swingDelay = 0.09
      if ctl.mode=="BYPASS" then
        local direction = pos - myPos
        local flat = Vector3.new(direction.X, 0, direction.Z)
        local flatDir = flat.Magnitude > 0.01 and flat.Unit or Vector3.zero
        local desiredHeight = pos.Y + 3.7
        local yOff = desiredHeight - myPos.Y
        local yVel = yOff * 19.5
        if h.FloorMaterial ~= Enum.Material.Air then
          yVel = math.max(yVel, 13)
        end
        yVel = math.clamp(yVel, -70, 110)
        desired = safeVec3(Vector3.new(flatDir.X * speed, yVel, flatDir.Z * speed))
        lerpAlpha = 0.8
        swingRange = 8
        swingDelay = 0.08
        if direction.Magnitude > 0.5 then
          local goalCF = CFrame.lookAt(myPos, pos)
          local rel = r.CFrame:ToObjectSpace(goalCF)
          local rx, ry, rz = rel:ToEulerAnglesXYZ()
          if rx == rx and ry == ry and rz == rz then
            rx = math.clamp(rx, -2.5, 2.5)
            ry = math.clamp(ry, -2.5, 2.5)
            rz = math.clamp(rz, -2.5, 2.5)
            angular = safeVec3(r.CFrame:VectorToWorldSpace(Vector3.new(rx * 42, ry * 42, rz * 42)))
          end
        end
      else
        local look = target.CFrame.LookVector
        local predictPos = pos + targetVel * 0.13 + look * 0.25
        local direction = predictPos - myPos
        local flat = Vector3.new(direction.X, 0, direction.Z)
        local flatDir = flat.Magnitude > 0.01 and flat.Unit or Vector3.zero
        local yOff = (pos.Y + 3.6) - myPos.Y
        local yVel = yOff * 18 + targetVel.Y * 0.75
        if h.FloorMaterial ~= Enum.Material.Air then
          yVel = math.max(yVel, 12)
        end
        yVel = math.clamp(yVel, -75, 115)
        desired = safeVec3(Vector3.new(flatDir.X * speed, yVel, flatDir.Z * speed))
        lerpAlpha = 0.85
        swingRange = 5.5
        swingDelay = 0.09
        local predictTime = math.clamp(targetVel.Magnitude / 140, 0.04, 0.18)
        local predictedPos = pos + targetVel * predictTime
        if (predictedPos - myPos).Magnitude > 0.5 then
          local goalCF = CFrame.lookAt(myPos, predictedPos)
          local rel = r.CFrame:ToObjectSpace(goalCF)
          local rx, ry, rz = rel:ToEulerAnglesXYZ()
          if rx == rx and ry == ry and rz == rz then
            rx = math.clamp(rx, -2.4, 2.4)
            ry = math.clamp(ry, -2.4, 2.4)
            rz = math.clamp(rz, -2.4, 2.4)
            angular = safeVec3(r.CFrame:VectorToWorldSpace(Vector3.new(rx * 40, ry * 40, rz * 40)))
          end
        end
      end
      local applied = safeVec3(r.AssemblyLinearVelocity:Lerp(desired, lerpAlpha))
      r.AssemblyAngularVelocity = angular
      r.AssemblyLinearVelocity = applied
      ctl.angularWritten = angular
      ctl.velocityWritten = applied
      local bat = findBat(c)
      if bat and bat.Parent ~= c then pcall(function() h:EquipTool(bat) end) end
      if bat and (pos - myPos).Magnitude <= swingRange and now - ctl.lastSwing >= swingDelay then
        ctl.lastSwing = now
        pcall(function()
          bat:Activate()
          local rem = bat:FindFirstChildWhichIsA("RemoteEvent", true)
          if rem then rem:FireServer() end
        end)
      end
      return
    elseif ctl.mode=="BYPASS" then
      if ctl.version=="V2" then
        local forward=target.CFrame.LookVector
        aim=pos+forward*(target.AssemblyLinearVelocity.Magnitude<0.1 and 1.5 or 5)
      elseif ctl.version=="V3" then
        if ctl.lastPos then
          local obs=(pos-ctl.lastPos)/interval
          local change=obs-ctl.vel
          if change.Magnitude>200 then obs=ctl.vel+change.Unit*200 end
          ctl.accel=ctl.accel:Lerp((obs-ctl.vel)/interval,.25)
          ctl.vel=obs
          ctl.smooth=ctl.smooth:Lerp(obs,.35)
        end
        aim=pos+ctl.smooth*.10+ctl.accel*.12*.005
        local eh=target.Parent and target.Parent:FindFirstChildOfClass("Humanoid")
        if eh and eh.FloorMaterial==Enum.Material.Air then
          aim=aim+Vector3.new(0,-.5*workspace.Gravity*.01,0)
        end
        speed=math.clamp(speed,1,200)
      else
        if now-ctl.lastPing>=.5 then
          ctl.lastPing=now
          pcall(function() ctl.ping=math.clamp(LP:GetNetworkPing(),.03,.25) end)
        end
        if ctl.lastPos then
          local obs=(pos-ctl.lastPos)/interval
          local delta=obs-ctl.vel
          if delta.Magnitude>150 then obs=ctl.vel+delta.Unit*150 end
          local horiz=Vector3.new(obs.X,0,obs.Z)
          if horiz.Magnitude>80 then horiz=horiz.Unit*80;obs=Vector3.new(horiz.X,obs.Y,horiz.Z) end
          ctl.accel=ctl.accel:Lerp((obs-ctl.vel)/interval,.3)
          ctl.vel=obs;ctl.smooth=ctl.smooth:Lerp(obs,.2)
        end
        local eh=target.Parent and target.Parent:FindFirstChildOfClass("Humanoid")
        local airborne=eh and eh.FloorMaterial==Enum.Material.Air
        ctl.airTime=airborne and ctl.airTime+interval or 0
        local v=ctl.smooth
        if airborne and ctl.airTime>=.08 then v=Vector3.new(v.X*.8,ctl.vel.Y,v.Z*.8) end
        local predict=ctl.ping+1/60
        aim=pos+v*predict+ctl.accel*(.3*predict*predict*.5)
        if airborne then aim=aim+v*.242+Vector3.new(0,-.5*196.2*.242*.242,0)
        else aim=aim+v*.242 end
        local flat=Vector3.new(v.X,0,v.Z)
        if flat.Magnitude>1 then aim=aim+flat.Unit*3 end
        speed=math.clamp(speed,1,200)
      end
    else
      aim=pos+target.AssemblyLinearVelocity*p.lead+target.CFrame.LookVector*(ctl.version=="V4" and .6 or .3)
    end
    ctl.lastPos=pos;ctl.lastTime=now
    local diff=aim-r.Position
    local flat=Vector3.new(diff.X,0,diff.Z)
    h.AutoRotate=false
    local activeLift = flat.Magnitude > 3.5 and p.lift or 0.4
    local y=math.clamp((aim.Y+activeLift-r.Position.Y)*18+(ctl.smooth and ctl.smooth.Y or target.AssemblyLinearVelocity.Y)*.5,-65,85)
    if h.FloorMaterial~=Enum.Material.Air and (aim.Y - r.Position.Y) > 1.5 then y=math.max(y,13) end
    local desired = flat.Magnitude > 0.15 and Vector3.new(flat.Unit.X*speed,y,flat.Unit.Z*speed) or Vector3.new(0,y,0)
    local angular = Vector3.zero
    if flat.Magnitude > 0.6 then
      local lookAtPos = Vector3.new(aim.X, r.Position.Y, aim.Z)
      local targetCF = CFrame.lookAt(r.Position, lookAtPos)
      local relative = r.CFrame:Inverse() * targetCF
      local ax, ay, az = relative:ToEulerAnglesXYZ()
      if ax == ax and ay == ay and az == az then
        angular = r.CFrame:VectorToWorldSpace(Vector3.new(
          math.clamp(ax, -2.5, 2.5) * p.turn,
          math.clamp(ay, -2.8, 2.8) * p.turn,
          math.clamp(az, -2.5, 2.5) * p.turn
        ))
      end
    end
    desired = safeVec3(desired)
    angular = safeVec3(angular)
    local applied = safeVec3(r.AssemblyLinearVelocity:Lerp(desired, p.response))
    r.AssemblyAngularVelocity = angular
    r.AssemblyLinearVelocity = applied
    ctl.angularWritten=angular;ctl.velocityWritten=applied
    local bat=findBat(c)
    if bat and bat.Parent~=c then pcall(function() h:EquipTool(bat) end) end
    local range=ctl.version=="V5" and 13 or (ctl.mode=="BYPASS" and (ctl.version=="V4" and 13 or 12) or 8)
    local delay=ctl.version=="V5" and .04 or (ctl.mode=="BYPASS" and (ctl.version=="V4" and .25 or .08) or p.interval)
    if bat and (pos-r.Position).Magnitude<=range and now-ctl.lastSwing>=delay then
      ctl.lastSwing=now
      pcall(function()
        bat:Activate()
        local rem=bat:FindFirstChildWhichIsA("RemoteEvent",true)
        if rem then rem:FireServer() end
      end)
    end
  end
  local function setActive(v,mode,on)
    if ctl.connection then ctl.connection:Disconnect();ctl.connection=nil end
    if ctl.renderConn then ctl.renderConn:Disconnect();ctl.renderConn=nil end
    ctl.enabled=false
    release();resetPrediction()
    if v and profiles[v] then ctl.version=v end
    if mode=="NORMAL" or mode=="BYPASS" then ctl.mode=mode end
    if on then
      ctl.character=LP.Character
      ctl.enabled=true
      -- Suspend Adapt's regular aimbot before running NTXA's independent chase.
      if _G._AdaptSafeModeSetAction then pcall(_G._AdaptSafeModeSetAction,"aimbot",false) end
      if _G._AmbitiousStartChaseRagdollWatcher then pcall(_G._AmbitiousStartChaseRagdollWatcher) end
      if _G._SoloSetAimbotMoveLock then _G._SoloSetAimbotMoveLock(true) end
      ctl.renderConn=RunService.RenderStepped:Connect(function()
        if not ctl.enabled then return end
        local c=LP.Character
        local r=c and c:FindFirstChild("HumanoidRootPart")
        local h=c and c:FindFirstChildOfClass("Humanoid")
        if h and h.Health>0 then
          pcall(function() h:Move(Vector3.zero, false) end)
        end
        if r and ctl.velocityWritten then
          r.AssemblyLinearVelocity=ctl.velocityWritten
          if ctl.angularWritten then r.AssemblyAngularVelocity=ctl.angularWritten end
        elseif r then
          r.AssemblyLinearVelocity=Vector3.new(0, r.AssemblyLinearVelocity.Y, 0)
        end
      end)
      ctl.connection=RunService.Heartbeat:Connect(step)
    end
    if _G._AdaptNTXAUpdateButtons then pcall(_G._AdaptNTXAUpdateButtons) end
  end
  _G.AdaptNTXABatAimbot={set=function(version,mode) setActive(version,mode,true) end,
    stop=function() setActive(nil,nil,false) end,
    current=function()return ctl.enabled,ctl.version,ctl.mode end}
  LP.CharacterRemoving:Connect(function(character)
    if ctl.character==character then release();resetPrediction();ctl.character=nil end
  end)
  LP.CharacterAdded:Connect(function(character)
    release();resetPrediction();ctl.character=character
  end)
  -- NTXA buttons are embedded in the existing Adapt Combat tab.
  if _G._AdaptNTXAUpdateButtons then pcall(_G._AdaptNTXAUpdateButtons) end
end
-- END NTXA BAT AIMBOT PORT


-- NTXA COMBAT DEFENSES PORT BEGIN
-- Separate namespace. Source Anti Void/Anti Bat port with isolated state.
do
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local LP = Players.LocalPlayer
_G.AdaptNTXADefense = _G.AdaptNTXADefense or {}
_G._AdaptNTXAWaitCharReady = function(char, timeout)
    local deadline = os.clock() + (timeout or 10)
    while os.clock() < deadline do
        if not char or not char.Parent or LP.Character ~= char then return false end
        if char:FindFirstChild("HumanoidRootPart") and char:FindFirstChildOfClass("Humanoid") then return true end
        task.wait(0.05)
    end
    return false
end
-- >>> ANTI VOID BEGIN
-- ============================================================
-- ANTI VOID
-- Sempre attivo dall'esecuzione. Un thread per giocatore tiene 0.07s
-- di storico dei CFrame: se in quella finestra copre 150 stud totali
-- oppure 100 stud di sola Y, e' un teletrasporto. La posizione buona e'
-- quella del campione piu' vecchio dello storico, e il TP viene contato
-- solo se partiva dalla Safe Zone. Da li' in poi TP Bat, aimbot V1/V2,
-- Bat Counter, Look At Enemy, ESP e tracker puntano al punto d'origine.
-- ============================================================
do
  -- Limiti di coordinate della Safe Zone
  local MAP_BOUNDS = {
    MinX = -535.7,
    MaxX = -422.0,
    MinY = -7.9,
    MaxY = 115.0,
    MinZ = -72.0,
    MaxZ = 193.3,
  }

  -- Finestra UNICA da 0.07s per tutti gli assi:
  --   150 stud di distanza totale (X/Z/Y)  oppure  100 stud di sola Y
  local TP_TOTAL   = 150
  local TP_DELTA_Y = 100
  local WINDOW     = 0.07
  -- Il fantasma non sparisce rientrando nella zona: sparisce quando il
  -- giocatore ha camminato WALK_CLEAR stud ORIZZONTALI dentro la zona.
  -- La Y e' esclusa dal conteggio: cadere o salire non lo cancella.
  local WALK_CLEAR = 15
  local STEP_MAX   = 50   -- oltre questo non e' camminata, non si accumula

  local function enabled() return _G.AdaptNTXAAntiVoidEnabled == true end

  local ghost   = setmetatable({}, { __mode = "k" })  -- [player] = posizione d'origine
  local ghostCF = setmetatable({}, { __mode = "k" })  -- [player] = CFrame d'origine
  local isOutOf = setmetatable({}, { __mode = "k" })  -- [player] = bool
  local tracked = setmetatable({}, { __mode = "k" })  -- [player] = true (thread gia' avviato)

  local function isWithinBounds(pos)
    if typeof(pos) ~= "Vector3" then return false end
    return pos.X >= MAP_BOUNDS.MinX and pos.X <= MAP_BOUNDS.MaxX
       and pos.Y >= MAP_BOUNDS.MinY and pos.Y <= MAP_BOUNDS.MaxY
       and pos.Z >= MAP_BOUNDS.MinZ and pos.Z <= MAP_BOUNDS.MaxZ
  end

  -- Richiamata SOLO quando un teleport viene confermato
  local function onTeleportDetected(player, originCFrame)
    isOutOf[player] = true
    ghostCF[player] = originCFrame
    ghost[player]   = originCFrame.Position
  end


  -- ============================================================
  -- RESCUE (rete di sicurezza per LP)
  -- Se LP finisce fuori dalla Safe Zone (void part assente, fling,
  -- micro-bug) viene riportato all'ultima posizione sicura a terra.
  -- Attivo solo quando Anti Void e' acceso. Cooldown zero: interviene
  -- ad ogni Heartbeat finche' LP non e' rientrato nella zona.
  -- ============================================================
  local _rescueLastSafePos = nil   -- ultima pos a terra dentro la zona
  local _rescueSpawnOrigin = nil   -- prima pos sicura rilevata all'accensione
  local _rescueLastRescue  = 0     -- os.clock() dell'ultimo rescue
  local RESCUE_COOLDOWN    = 0     -- istantaneo (come in NTXADUELS_2_)
  local RESCUE_UPDATE_INT  = 0.1   -- ogni quanto aggiornare il checkpoint
  local _rescueLastUpdate  = 0

  local function _rescueUpdateCheckpoint()
    local c   = LP.Character
    local hrp = c and c:FindFirstChild("HumanoidRootPart")
    local hum = c and c:FindFirstChildOfClass("Humanoid")
    if not (hrp and hum) then return end
    local now = os.clock()
    if now - _rescueLastUpdate < RESCUE_UPDATE_INT then return end
    _rescueLastUpdate = now
    local pos = hrp.Position
    if not _rescueSpawnOrigin and isWithinBounds(pos) then
      _rescueSpawnOrigin = pos
    end
    -- salva checkpoint solo se e' a terra (non in aria) e dentro la zona
    if hum.FloorMaterial ~= Enum.Material.Air and isWithinBounds(pos) then
      _rescueLastSafePos = pos
    end
  end

  local function _rescueTryRescue()
    local c   = LP.Character
    local hrp = c and c:FindFirstChild("HumanoidRootPart")
    if not (hrp and hrp.Parent) then return end
    if isWithinBounds(hrp.Position) then return end
    local now = os.clock()
    if now - _rescueLastRescue < RESCUE_COOLDOWN then return end
    _rescueLastRescue = now
    local dest = _rescueLastSafePos or _rescueSpawnOrigin
    if dest and isWithinBounds(dest) then
      pcall(function()
        hrp.AssemblyLinearVelocity  = Vector3.zero
        hrp.AssemblyAngularVelocity = Vector3.zero
        hrp.CFrame = CFrame.new(dest + Vector3.new(0, 3, 0))
      end)
    end
  end

  -- Heartbeat dedicato al rescue LP. Si registra una sola volta
  -- e controlla enabled() ogni frame: zero overhead quando spento.
  RunService.Heartbeat:Connect(function()
    if not enabled() then return end
    _rescueUpdateCheckpoint()
    _rescueTryRescue()
  end)

  -- Resetta il checkpoint al respawn di LP: la nuova vita riparte da zero
  LP.CharacterAdded:Connect(function()
    _rescueLastSafePos = nil
    _rescueSpawnOrigin = nil
    _rescueLastRescue  = 0
    _rescueLastUpdate  = 0
  end)
  -- ============================================================
  -- FINE RESCUE
  -- ============================================================

  local function trackPlayer(player)
    if player == LP then return end
    if tracked[player] then return end
    tracked[player] = true

    local history      = {}
    local walkedXZ     = 0     -- spostamento orizzontale accumulato a piedi
    local lastCheckPos = nil

    task.spawn(function()
      while player and player.Parent do
        -- Poll passivo finche' l'Anti Void e' spento: nessun overhead.
        -- Il giocatore e' gia' in tracked, quindi se viene acceso basta
        -- uscire dal poll e il ciclo attivo riparte immediatamente.
        if not enabled() then
          -- Resetta lo stato in modo che la prima rilevazione sia pulita
          isOutOf[player] = false
          history      = {}
          walkedXZ     = 0
          lastCheckPos = nil
          task.wait(0.5)
        else
          local char = player.Character
          local hrp  = char and char:FindFirstChild("HumanoidRootPart")
          local hum  = char and char:FindFirstChildOfClass("Humanoid")

          if hrp and hum and hum.Health > 0 then
            local now = tick()
            local currentCFrame = hrp.CFrame
            local currentPos = currentCFrame.Position

            if isOutOf[player] then
              -- FASE 1: fantasma attivo, si misura solo la camminata X/Z
              if lastCheckPos then
                local moveVector = currentPos - lastCheckPos
                local moveXZ = Vector3.new(moveVector.X, 0, moveVector.Z).Magnitude
                if moveXZ < STEP_MAX and isWithinBounds(currentPos) then
                  walkedXZ = walkedXZ + moveXZ
                end
              end
              lastCheckPos = currentPos

              if walkedXZ >= WALK_CLEAR then
                isOutOf[player] = false
                ghost[player]   = currentPos
                ghostCF[player] = currentCFrame
                history      = {}
                walkedXZ     = 0
                lastCheckPos = nil
              end
            else
              -- FASE 2: nessun fantasma, si cerca il teletrasporto
              walkedXZ     = 0
              lastCheckPos = currentPos
              ghost[player]   = currentPos
              ghostCF[player] = currentCFrame

              table.insert(history, {time = now, cframe = currentCFrame})
              while #history > 0 and (now - history[1].time) > WINDOW do
                table.remove(history, 1)
              end

              local oldest = history[1]
              if oldest then
                local totalDistance = (currentPos - oldest.cframe.Position).Magnitude
                local deltaY = math.abs(currentPos.Y - oldest.cframe.Position.Y)

                if totalDistance >= TP_TOTAL or deltaY >= TP_DELTA_Y then
                  local refCFrame = oldest.cframe
                  local refPos = refCFrame.Position
                  local studsTraveledVector = currentPos - refPos
                  local exactOriginPos = currentPos - studsTraveledVector
                  local exactCFrame = CFrame.new(exactOriginPos) * (refCFrame - refCFrame.Position)

                  if isWithinBounds(exactOriginPos) then
                    onTeleportDetected(player, exactCFrame)
                  end
                  history = {}
                end
              end
            end
          else
            -- morto o senza character: niente fantasma
            isOutOf[player] = false
            history      = {}
            walkedXZ     = 0
            lastCheckPos = nil
          end
          RunService.Heartbeat:Wait()
        end
      end
      tracked[player] = nil
    end)
  end

  Players.PlayerAdded:Connect(trackPlayer)

  -- I thread partono all'accensione e muoiono allo spegnimento: da spento
  -- il modulo non tiene niente in esecuzione.
  local function startAll()
    for _, plr in ipairs(Players:GetPlayers()) do trackPlayer(plr) end
  end

  local function stopAll()
    for plr in pairs(isOutOf) do isOutOf[plr] = false end
  end

  local function posFor(player, rawPos)
    if not player or not enabled() then return rawPos, false end
    if isOutOf[player] then
      local g = ghost[player]
      if g then return g, true end
    end
    return rawPos, false
  end

  -- Come sopra ma partendo da una BasePart del nemico
  local function posForPart(part, rawPos)
    if not part then return rawPos, false end
    local model = part:FindFirstAncestorOfClass("Model")
    local player = model and Players:GetPlayerFromCharacter(model)
    return posFor(player, rawPos or part.Position)
  end

  _G.AdaptNTXAAntiVoidEnabled = _G.AdaptNTXAAntiVoidEnabled == true

  -- Avvia subito un thread per ogni giocatore gia' presente.
  -- I thread fanno poll passivo se Anti Void e' spento, tracking attivo
  -- se e' acceso: nessun giocatore viene perso indipendentemente dallo stato.
  startAll()

  _G.AdaptNTXAAntiVoid = {
    setEnabled = function(on)
      on = on and true or false
      local was = _G.AdaptNTXAAntiVoidEnabled == true
      _G.AdaptNTXAAntiVoidEnabled = on
      if on and not was then
        -- Per sicurezza: aggiunge thread per giocatori entrati nel frattempo
        startAll()
      elseif (not on) and was then
        stopAll()
      end
    end,
    isEnabled  = function() return _G.AdaptNTXAAntiVoidEnabled == true end,
    bounds     = MAP_BOUNDS,
    posFor     = posFor,
    posForPart = posForPart,
    isOut      = function(player) return player and isOutOf[player] == true end,
    ghostOf    = function(player) return player and ghost[player] or nil end,
  }

  -- ---------- REPLICA ESP SULLA POSIZIONE FANTASMA ----------
  -- Al TP si congela una copia del corpo sul CFrame d'origine calcolato
  -- dal tracker, con lo stesso contorno e overhead dell'ESP. L'ESP vero
  -- viene nascosto, cosi' non lo segue nel void.
  -- NB: ghostCF e' quello dichiarato sopra dal tracker, non ridichiararlo
  -- qui o la replica leggerebbe una tabella sempre vuota.
  local replicas   = {}
  local ghostFolder = nil

  local function ensureFolder()
    if ghostFolder and ghostFolder.Parent then return ghostFolder end
    ghostFolder = Instance.new("Folder")
    ghostFolder.Name = "AdaptNTXAAntiVoid"
    ghostFolder.Parent = workspace
    return ghostFolder
  end

  -- Mostra o nasconde l'ESP reale del nemico
  local function setRealESP(char, visible)
    if not char then return end
    local hl = char:FindFirstChild("AdaptNTXAHUBESP")
    if hl then pcall(function() hl.Enabled = visible end) end
    local head = char:FindFirstChild("Head")
    local tag = head and head:FindFirstChild("AdaptNTXAHUBESPTag")
    if tag then pcall(function() tag.Enabled = visible end) end
  end

  local function clearReplica(plr)
    local r = replicas[plr]
    if r then pcall(function() r:Destroy() end) end
    replicas[plr] = nil
  end

  local function buildReplica(plr, char, cf)
    clearReplica(plr)
    -- ESP spento: non si crea niente. Il resto (TP Bat, aimbot, tracker,
    -- Look At Enemy) continua a funzionare sulla posizione fantasma.
    if not char:FindFirstChild("AdaptNTXAHUBESP") then return end
    local ok, clone = pcall(function()
      char.Archivable = true
      return char:Clone()
    end)
    if not ok or not clone then return end

    -- Congela la copia: niente script, niente fisica, niente collisioni
    for _, d in ipairs(clone:GetDescendants()) do
      if d:IsA("Script") or d:IsA("LocalScript") or d:IsA("Humanoid") then
        pcall(function() d:Destroy() end)
      elseif d:IsA("BasePart") then
        d.Anchored   = true
        d.CanCollide = false
        d.CanQuery   = false
        d.CanTouch   = false
      end
    end
    clone.Name = "GhostReplica_" .. tostring(plr.Name)
    clone.Parent = ensureFolder()
    pcall(function() clone:PivotTo(cf) end)

    -- L'ESP e il suo overhead sono figli del personaggio, quindi la copia
    -- se li porta dietro identici e congelati sull'ultimo valore.
    local hl = clone:FindFirstChild("AdaptNTXAHUBESP")
    if hl then pcall(function() hl.Enabled = true end) end

    local cloneHead = clone:FindFirstChild("Head")
    local tag = cloneHead and cloneHead:FindFirstChild("AdaptNTXAHUBESPTag")
    if tag then
      pcall(function() tag.Enabled = true end)
      -- scritta VOID sotto la velocita', al posto dove stava il nome
      local box = tag:FindFirstChildOfClass("Frame") or tag
      local vl = Instance.new("TextLabel")
      vl.Name = "VoidTag"
      vl.Size = UDim2.new(1, -10, 0, 16)
      vl.Position = UDim2.new(0, 5, 0, 19)
      vl.BackgroundTransparency = 1
      vl.TextColor3 = Color3.fromRGB(255, 255, 255)
      vl.Font = Enum.Font.GothamBlack
      vl.TextSize = 16
      vl.TextStrokeTransparency = 0.4
      vl.Text = "VOID"
      vl.Parent = box
    end

    replicas[plr] = clone
  end

  -- Repliche ESP: lo stato lo tiene gia' il thread di tracciamento
  local lastMarkerTick = 0
  RunService.Heartbeat:Connect(function()
    local now = os.clock()
    if now - lastMarkerTick < 0.1 then return end
    lastMarkerTick = now

    for _, plr in ipairs(Players:GetPlayers()) do
      if plr ~= LP then
        local c   = plr.Character
        local hrp = c and c:FindFirstChild("HumanoidRootPart")
        local hum = c and c:FindFirstChildOfClass("Humanoid")
        local out = enabled() and (hrp ~= nil) and (hum ~= nil) and hum.Health > 0 and isOutOf[plr] == true
        if out and ghostCF[plr] then
          setRealESP(c, false)
          if not replicas[plr] or not replicas[plr].Parent then
            buildReplica(plr, c, ghostCF[plr])
          end
        else
          if replicas[plr] then
            clearReplica(plr)
            setRealESP(c, true)
          end
        end
      end
    end
  end)

  Players.PlayerRemoving:Connect(function(plr)
    ghost[plr] = nil
    isOutOf[plr] = nil
    ghostCF[plr] = nil
    tracked[plr] = nil
    clearReplica(plr)
  end)
end
-- <<< ANTI VOID END
-- >>> ANTI BAT BEGIN
-- ============================================================
-- ANTI BAT
-- Quando attivo: lo Speed Booster smette di usare il suo proxy (che
-- viene distrutto) e scrive su root.Velocity. L'Infinite Jump non viene
-- toccato e continua a usare il suo proxy. Spegnendolo il proxy dello
-- speed booster viene ricreato: nulla di permanente.
-- ============================================================
do
  local AntiBatConn = nil
  local Speed     = 10000
  local Angle     = 0
  local Direction = 1   -- 1 aumenta, -1 diminuisce

  local function stopAntiBat()
    if AntiBatConn then
      pcall(function() AntiBatConn:Disconnect() end)
      AntiBatConn = nil
    end
    Speed     = 10000
    Angle     = 0
    Direction = 1
    _G._AdaptNTXAAntiBatDesiredXZ = nil
    _G._AdaptNTXAAntiBatSpiking = false
  end

  local function startAntiBat()
    stopAntiBat()
    AntiBatConn = RunService.Heartbeat:Connect(function()
      if not _G.AdaptNTXAAntiBatEnabled or _G._AmbitiousSlowFallActive or _G._AmbitiousZigZagFalling then return end
      local char = LP.Character
      local root = char and char:FindFirstChild("HumanoidRootPart")
      if not root or not root.Parent then return end

      -- Salva la velocita' originale X e Z
      local origXZ = Vector3.new(root.Velocity.X, 0, root.Velocity.Z)

      -- Speed oscillante tra 10000 e 20000
      Speed = Speed + (50 * Direction)
      if Speed >= 20000 then
        Speed = 20000
        Direction = -1
      elseif Speed <= 10000 then
        Speed = 10000
        Direction = 1
      end

      -- Angolo caotico + raggio variabile
      Angle = Angle + (math.random() * 0.5)
      local radius = Speed + math.random(-5000, 5000)
      local newX = math.cos(Angle) * radius
      local newZ = math.sin(Angle) * radius

      _G._AdaptNTXAAntiBatSpiking = true
      root.Velocity = Vector3.new(newX, root.Velocity.Y, newZ)

      RunService.RenderStepped:Wait()

      -- Ripristina X e Z: se lo speed booster ha una velocita' desiderata
      -- si riscrive quella (la speed dell'hub), altrimenti l'originale.
      if root.Parent then
        local want = _G._AdaptNTXAAntiBatDesiredXZ
        if want then
          root.Velocity = Vector3.new(want.X, root.Velocity.Y, want.Z)
        else
          root.Velocity = Vector3.new(origXZ.X, root.Velocity.Y, origXZ.Z)
        end
      end
      _G._AdaptNTXAAntiBatSpiking = false
    end)
  end

  _G.AdaptNTXAAntiBatEnabled = _G.AdaptNTXAAntiBatEnabled == true

  -- Ogni fase e' protetta: se una fallisce non blocca le altre e si vede l'errore
  local function step(_, fn)
    pcall(fn)
  end

  _G.AdaptNTXAAntiBat = {
    setEnabled = function(on)
      on = on and true or false
      _G.AdaptNTXAAntiBatEnabled = on
      if on then
        step("startAntiBat", startAntiBat)
      else
        step("stopAntiBat", stopAntiBat)
      end
    end,
    isEnabled = function() return _G.AdaptNTXAAntiBatEnabled == true end,
  }

  -- Watchdog permanente: se il flag e' acceso ma i loop non ci sono
  -- (errore, respawn, disconnessione imprevista) li riavvia da solo.
  task.spawn(function()
    while true do
      task.wait(0.5)
      if _G.AdaptNTXAAntiBatEnabled then
        if not AntiBatConn then
          step("watchdog:start", startAntiBat)
        end
      elseif AntiBatConn then
        step("watchdog:stop", stopAntiBat)
      end
    end
  end)

  -- Respawn: il vecchio HRP e' morto, si riparte pulito
  LP.CharacterAdded:Connect(function(char)
    if _G._AdaptNTXAWaitCharReady then _G._AdaptNTXAWaitCharReady(char, 10) end
    if _G.AdaptNTXAAntiBatEnabled then
      startAntiBat()
    else
      stopAntiBat()
    end
  end)
end
-- <<< ANTI BAT END
_G.AdaptNTXADefense.AntiVoid = _G.AdaptNTXAAntiVoid
_G.AdaptNTXADefense.AntiBat = _G.AdaptNTXAAntiBat
end

-- Anti Die based on NTXA's Humanoid safeguards, with explicit cleanup.
do
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local LP = Players.LocalPlayer
local active = false
local currentHum, currentChar
local connections = {}
local heartbeat
local respawn
local saved = nil
local forcefield
local function cleanup()
    for _, connection in ipairs(connections) do pcall(function() connection:Disconnect() end) end
    table.clear(connections)
    if heartbeat then heartbeat:Disconnect(); heartbeat = nil end
    if currentHum and currentHum.Parent and saved then
        pcall(function()
            currentHum:SetStateEnabled(Enum.HumanoidStateType.Dead, saved.dead)
            currentHum.BreakJointsOnDeath = saved.breakJoints
            currentHum.RequiresNeck = saved.requiresNeck
        end)
    end
    if forcefield and forcefield.Parent then forcefield:Destroy() end
    forcefield, currentHum, currentChar, saved = nil, nil, nil, nil
end
local function apply(char)
    cleanup()
    if not active or not char or char ~= LP.Character then return end
    local hum = char:FindFirstChildOfClass("Humanoid") or char:WaitForChild("Humanoid", 5)
    if not hum or not active or char ~= LP.Character then return end
    currentHum, currentChar = hum, char
    saved = {dead=hum:GetStateEnabled(Enum.HumanoidStateType.Dead), breakJoints=hum.BreakJointsOnDeath, requiresNeck=hum.RequiresNeck}
    pcall(function()
        hum:SetStateEnabled(Enum.HumanoidStateType.Dead, false)
        hum.BreakJointsOnDeath = false
        hum.RequiresNeck = false
        hum.Health = hum.MaxHealth
    end)
    forcefield = Instance.new("ForceField")
    forcefield.Name = "AdaptNTXAAntiDieForceField"
    forcefield.Visible = false
    forcefield.Parent = char
    table.insert(connections, hum.HealthChanged:Connect(function(health)
        if active and currentHum == hum and health <= 25 then
            pcall(function() hum.Health = hum.MaxHealth end)
        end
    end))
    heartbeat = RunService.Heartbeat:Connect(function()
        if not active or LP.Character ~= char then return end
        if hum.Parent and hum.Health <= 25 then pcall(function() hum.Health = hum.MaxHealth end) end
    end)
end
_G.AdaptNTXADefense = _G.AdaptNTXADefense or {}
_G.AdaptNTXADefense.AntiDie = {
    setEnabled = function(value)
        local on = value == true
        if active == on then return end
        active = on
        if active then
            if not respawn then
                respawn = LP.CharacterAdded:Connect(function(char)
                    task.defer(function() if active then apply(char) end end)
                end)
            end
            if LP.Character then apply(LP.Character) end
        else
            cleanup()
            if respawn then respawn:Disconnect(); respawn = nil end
        end
    end,
    isEnabled = function() return active end
}
end
-- NTXA COMBAT DEFENSES PORT END

-- SPACE HUB ANTI BAT V2 BEGIN
-- Only the Anti Bat velocity-desync engine is ported from "space hub anti bat.txt".
-- No GUI, config, keybind, ESP, or Infinite Jump is imported.
do
    local Players = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local UserInputService = game:GetService("UserInputService")
    local LP = Players.LocalPlayer
    local active = false
    local heartbeat = nil
    local jumpConn = nil
    local pendingJumpY = nil
    local generation = 0

    local function stop()
        active = false
        pendingJumpY = nil
        generation += 1
        if heartbeat then heartbeat:Disconnect(); heartbeat = nil end
    if jumpConn then jumpConn:Disconnect(); jumpConn = nil end
    end

    local function start()
        if active then return end
        -- V1 and V2 are mutually exclusive.
        local first = _G.AdaptNTXADefense and _G.AdaptNTXADefense.AntiBat
        if first and first.isEnabled() then first.setEnabled(false) end
        if type(_G._AdaptSetInfiniteJump) == "function" then
            pcall(_G._AdaptSetInfiniteJump, true)
          end
        active = true
        pendingJumpY = nil
        generation += 1
        local token = generation
        jumpConn = UserInputService.JumpRequest:Connect(function()
          if not active or token ~= generation or _G._AmbitiousTPDownJumpLocked or _G._AmbitiousSlowFallActive then return end
          pendingJumpY = 55
          local char = LP.Character
          local root = char and char:FindFirstChild("HumanoidRootPart")
          if root and root.Parent then
            local v = root.Velocity
            root.Velocity = Vector3.new(v.X, 55, v.Z)
          end
        end)
        heartbeat = RunService.Heartbeat:Connect(function()
            if not active or token ~= generation or _G._AmbitiousSlowFallActive or _G._AmbitiousZigZagFalling then return end
            local char = LP.Character
            local root = char and char:FindFirstChild("HumanoidRootPart")
            if not root or not root.Parent then return end
            local hum = char:FindFirstChildOfClass("Humanoid")
            local original = root.Velocity
            local origX, origZ = original.X, original.Z
            local targetY = original.Y
            if pendingJumpY then
              targetY = pendingJumpY
              pendingJumpY = nil
            elseif (UserInputService:IsKeyDown(Enum.KeyCode.Space) or (hum and hum.Jump == true)) and targetY < 30 then
                targetY = 50
              elseif targetY < -120 then
                  targetY = -40
                end
                root.Velocity = Vector3.new(math.random(-4000, 4000), targetY, math.random(-4000, 4000))
            RunService.RenderStepped:Wait()
            -- Do not write stale velocity after disabling, respawn, or character replacement.
            if active and token == generation and LP.Character == char and root.Parent then
                local currentY = root.Velocity.Y
                if pendingJumpY then
                  currentY = pendingJumpY
                  pendingJumpY = nil
                end
                root.Velocity = Vector3.new(origX, currentY, origZ)
            end
        end)
    end

    local api = {
        setEnabled = function(value)
            if value == true then start() else stop() end
            if _G._AdaptNTXADefenseRefresh then pcall(_G._AdaptNTXADefenseRefresh) end
        end,
        isEnabled = function() return active end
    }
    _G.AdaptNTXADefense = _G.AdaptNTXADefense or {}
    _G.AdaptNTXADefense.AntiBatV2 = api

    -- Enforce exclusivity regardless of whether V1 is toggled through the UI
    -- or by another script action.
    local first = _G.AdaptNTXADefense.AntiBat
    if first then
        local originalSet = first.setEnabled
        first.setEnabled = function(value)
            if value == true and active then stop() end
            originalSet(value)
            if _G._AdaptNTXADefenseRefresh then pcall(_G._AdaptNTXADefenseRefresh) end
        end
    end

end
-- SPACE HUB ANTI BAT V2 END
do
  local Players = game:GetService("Players")
  local LP = Players.LocalPlayer
  local chaseRagdollEnabled = false
  local chaseRagdollPlayerConns = {}
  local chaseRagdollCharConns = {}
  local chaseRagdollAddedConn = nil
  local chaseRagdollRemovingConn = nil
  local function isAnyAimbotOrTPBatOn()
    local ntxaOn = _G.AdaptNTXABatAimbot and select(1, _G.AdaptNTXABatAimbot.current()) == true or false
    local v1On = (_G._AdaptSafeModeActionActive and _G._AdaptSafeModeActionActive("aimbot") == true)
    or (_G._AdaptUnifiedAimbotIsActive and _G._AdaptUnifiedAimbotIsActive() == true)
    or false
    local tpBatOn = (_G._AdaptSnowTPBatEnabled == true)
    or (_G._AdaptSafeModeActionActive and _G._AdaptSafeModeActionActive("tpBat") == true)
    or false
    return ntxaOn or v1On or tpBatOn
  end
  local function onChaseEnemyRagdollStarted()
    if not chaseRagdollEnabled then return end
    if not isAnyAimbotOrTPBatOn() then return end
    if _G._AdaptUnifiedAimbotSetEnabled then
      pcall(_G._AdaptUnifiedAimbotSetEnabled, false)
    end
    if _G.AdaptNTXABatAimbot and _G.AdaptNTXABatAimbot.stop then
      pcall(_G.AdaptNTXABatAimbot.stop)
    end
    if _G._AdaptSafeModeSetAction then
      pcall(_G._AdaptSafeModeSetAction, "aimbot", false)
      pcall(_G._AdaptSafeModeSetAction, "tpBat", false)
    end
    if _G._AdaptAimbotV1Toggle then
      pcall(_G._AdaptAimbotV1Toggle, false)
    end
    if _G._AdaptSnowTPBatSetEnabled and _G._AdaptSnowTPBatEnabled then
      pcall(_G._AdaptSnowTPBatSetEnabled, false)
    end
    if _G._AdaptUnifiedAimbotSync then
      pcall(_G._AdaptUnifiedAimbotSync)
    end
    if _G._AdaptSyncMobile then
      pcall(_G._AdaptSyncMobile)
    end
  end
  local function setupChaseRagdollDetector(plr, enemyChar)
    if chaseRagdollCharConns[plr] then
      pcall(function() chaseRagdollCharConns[plr]:Disconnect() end)
      chaseRagdollCharConns[plr] = nil
    end
    local conn = enemyChar.DescendantAdded:Connect(function(d)
      if d:IsA("BallSocketConstraint") then
        onChaseEnemyRagdollStarted()
      end
    end)
    chaseRagdollCharConns[plr] = conn
    enemyChar.AncestryChanged:Connect(function(_, parent)
      if not parent then
        pcall(function() conn:Disconnect() end)
        if chaseRagdollCharConns[plr] == conn then
          chaseRagdollCharConns[plr] = nil
        end
      end
    end)
    return conn
  end
  local function watchChaseEnemyPlayer(plr)
    if plr == LP then return end
    if chaseRagdollPlayerConns[plr] then
      pcall(function() chaseRagdollPlayerConns[plr]:Disconnect() end)
    end
    chaseRagdollPlayerConns[plr] = plr.CharacterAdded:Connect(function(char)
      if char and chaseRagdollEnabled then
        setupChaseRagdollDetector(plr, char)
      end
    end)
    if plr.Character then
      setupChaseRagdollDetector(plr, plr.Character)
    end
  end
  function _G._AmbitiousStartChaseRagdollWatcher()
    if chaseRagdollEnabled then return end
    chaseRagdollEnabled = true
    if chaseRagdollAddedConn then chaseRagdollAddedConn:Disconnect() end
    chaseRagdollAddedConn = Players.PlayerAdded:Connect(watchChaseEnemyPlayer)
    for _, plr in ipairs(Players:GetPlayers()) do
      watchChaseEnemyPlayer(plr)
    end
    if chaseRagdollRemovingConn then chaseRagdollRemovingConn:Disconnect() end
    chaseRagdollRemovingConn = Players.PlayerRemoving:Connect(function(plr)
      if chaseRagdollPlayerConns[plr] then
        pcall(function() chaseRagdollPlayerConns[plr]:Disconnect() end)
        chaseRagdollPlayerConns[plr] = nil
      end
      if chaseRagdollCharConns[plr] then
        pcall(function() chaseRagdollCharConns[plr]:Disconnect() end)
        chaseRagdollCharConns[plr] = nil
      end
    end)
  end
  function _G._AmbitiousStopChaseRagdollWatcher()
    chaseRagdollEnabled = false
    if chaseRagdollAddedConn then
      chaseRagdollAddedConn:Disconnect()
      chaseRagdollAddedConn = nil
    end
    if chaseRagdollRemovingConn then
      chaseRagdollRemovingConn:Disconnect()
      chaseRagdollRemovingConn = nil
    end
    for _, conn in pairs(chaseRagdollPlayerConns) do
      pcall(function() conn:Disconnect() end)
    end
    table.clear(chaseRagdollPlayerConns)
    for _, conn in pairs(chaseRagdollCharConns) do
      pcall(function() conn:Disconnect() end)
    end
    table.clear(chaseRagdollCharConns)
  end
  _G._AmbitiousStartChaseRagdollWatcher()
end


-- ============================================================
-- FA4E7XX ANTI BAT V3 ENGINE (velocity desync ±4000 X/Z + RenderStepped restore)
-- ============================================================
do
    local Players = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local LocalPlayer = Players.LocalPlayer
    local active = false
    local antiBatConn = nil
    local antiBatBusy = false

    local function stopOtherAntiBats()
        local d = _G.AdaptNTXADefense
        if not d then return end
        if d.AntiBat and d.AntiBat.isEnabled and d.AntiBat.isEnabled() then
            d.AntiBat.setEnabled(false)
        end
        if d.AntiBatV2 and d.AntiBatV2.isEnabled and d.AntiBatV2.isEnabled() then
            d.AntiBatV2.setEnabled(false)
        end
    end

    local function enableAntiBatV3()
        if antiBatConn then return end
        stopOtherAntiBats()
        active = true
        antiBatBusy = false
        antiBatConn = RunService.Heartbeat:Connect(function()
            if not active or antiBatBusy or _G._AmbitiousSlowFallActive or _G._AmbitiousZigZagFalling then return end
            local char = LocalPlayer.Character
            if not char then return end
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if not hrp then return end

            antiBatBusy = true
            pcall(function()
                local vel = hrp.Velocity
                hrp.Velocity = Vector3.new(math.random(-4000, 4000), vel.Y, math.random(-4000, 4000))
                RunService.RenderStepped:Wait()
                if hrp and hrp.Parent then
                    -- keep the CURRENT Y so Infinite Jump's boost isn't wiped out
                    local cur = hrp.Velocity
                    hrp.Velocity = Vector3.new(vel.X, cur.Y, vel.Z)
                end
            end)
            antiBatBusy = false
        end)
    end

    local function disableAntiBatV3()
        active = false
        antiBatBusy = false
        if antiBatConn then
            antiBatConn:Disconnect()
            antiBatConn = nil
        end
    end

    _G.AdaptNTXADefense = _G.AdaptNTXADefense or {}
    _G.AdaptNTXADefense.AntiBatV3 = {
        setEnabled = function(value)
            if value == true then
                enableAntiBatV3()
            else
                disableAntiBatV3()
            end
            if _G._AdaptNTXADefenseRefresh then pcall(_G._AdaptNTXADefenseRefresh) end
        end,
        isEnabled = function()
            return active == true
        end,
    }

    -- Ensure V1 and V2 also turn off V3 when enabled
    for _, k in ipairs({"AntiBat", "AntiBatV2"}) do
        local mod = _G.AdaptNTXADefense[k]
        if mod and mod.setEnabled then
            local origSet = mod.setEnabled
            mod.setEnabled = function(value)
                if value == true and active then
                    disableAntiBatV3()
                end
                origSet(value)
                if _G._AdaptNTXADefenseRefresh then pcall(_G._AdaptNTXADefenseRefresh) end
            end
        end
    end
end

-- ============================================================
-- AMBITIOUS HUB CUSTOM TOOLS (BAT ONLY: DIAMOND SWORD & KATANA),
-- RAINBOW TOOLS, AND CUSTOM SOUNDS
-- ============================================================
do
    local _Players    = game:GetService("Players")
    local _RunService = game:GetService("RunService")
    local _LP         = _Players.LocalPlayer

    local CT_ITEMS = {
        { key = "Bat",    match = function(n) n = n:lower() return n:find("bat") ~= nil or n:find("slap") ~= nil end },
        { key = "Medusa", match = function(n) return n:lower():find("medusa") ~= nil end },
    }

    local function ctMatchItem(inst)
        if not (inst:IsA("Tool") or inst:IsA("Model") or inst:IsA("Accessory") or inst:IsA("BasePart")) then
            return nil
        end
        for _, item in ipairs(CT_ITEMS) do
            if item.match(inst.Name) then return item end
        end
        return nil
    end

    local function ctMatchBatOnly(inst)
        if not (inst:IsA("Tool") or inst:IsA("Model") or inst:IsA("Accessory") or inst:IsA("BasePart")) then
            return nil
        end
        local n = inst.Name:lower()
        if n:find("bat") ~= nil or n:find("slap") ~= nil then
            return CT_ITEMS[1]
        end
        return nil
    end

    local function isReplicaStuff(d)
        if d.Name == "LocalReplica" then return true end
        return d:FindFirstAncestor("LocalReplica") ~= nil
    end

    local CT_Trans = {}
    do
        local PRIORITY = { "custom", "rainbow", "transparent" }
        local baseline = setmetatable({}, { __mode = "k" })
        local claims   = setmetatable({}, { __mode = "k" })
        local guards   = setmetatable({}, { __mode = "k" })

        function CT_Trans.getBaseline(part)
            local b = baseline[part]
            if b ~= nil then return b end
            local ok, val = pcall(function() return part.Transparency end)
            if not ok then return nil end
            baseline[part] = val
            return val
        end

        local function wantedValue(part)
            local c = claims[part]
            if not c then return nil end
            for _, who in ipairs(PRIORITY) do
                if c[who] ~= nil then return c[who] end
            end
            return nil
        end

        local function setIfDifferent(part, v)
            local ok, cur = pcall(function() return part.Transparency end)
            if ok and cur ~= nil and math.abs(cur - v) <= 0.001 then return end
            pcall(function() part.Transparency = v end)
        end

        local function resolve(part)
            local v = wantedValue(part)
            if v ~= nil then
                setIfDifferent(part, v)
                return
            end
            local b = baseline[part]
            if b ~= nil then
                setIfDifferent(part, b)
            end
        end

        local function armGuard(part)
            if guards[part] then return end
            local ok, conn = pcall(function()
                return part:GetPropertyChangedSignal("Transparency"):Connect(function()
                    local v = wantedValue(part)
                    if v == nil then return end
                    local ok2, cur = pcall(function() return part.Transparency end)
                    if ok2 and cur ~= nil and math.abs(cur - v) > 0.001 then
                        pcall(function() part.Transparency = v end)
                    end
                end)
            end)
            if ok and conn then guards[part] = conn end
        end

        local function disarmGuard(part)
            local conn = guards[part]
            if conn then
                pcall(function() conn:Disconnect() end)
                guards[part] = nil
            end
        end

        function CT_Trans.enforce()
            for part, _ in pairs(claims) do
                if part.Parent then
                    local v = wantedValue(part)
                    if v ~= nil then
                        local ok, cur = pcall(function() return part.Transparency end)
                        if ok and cur ~= nil and math.abs(cur - v) > 0.001 then
                            pcall(function() part.Transparency = v end)
                        end
                    end
                end
            end
        end

        function CT_Trans.claim(part, who, value)
            if not part then return end
            if CT_Trans.getBaseline(part) == nil then return end
            local c = claims[part]
            if not c then c = {}; claims[part] = c end
            c[who] = value
            armGuard(part)
            resolve(part)
        end

        function CT_Trans.release(part, who)
            if not part then return end
            local c = claims[part]
            if not c then return end
            c[who] = nil
            if next(c) == nil then
                claims[part] = nil
                disarmGuard(part)
            end
            if part.Parent then resolve(part) end
        end
    end

    local CT_JANITORS = {}
    task.spawn(function()
        while true do
            task.wait(10)
            for _, fn in ipairs(CT_JANITORS) do pcall(fn) end
        end
    end)

    task.spawn(function()
        while true do
            task.wait(0.25)
            if _G.AmbitiousCustomToolsEnabled == true
            or _G.AmbitiousRainbowToolsEnabled == true then
                pcall(CT_Trans.enforce)
            end
        end
    end)

    -- ############################################################
    -- ##                     RAINBOW TOOLS                      ##
    -- ############################################################
    do
        local SPEED       = 0.35
        local SPREAD      = 0.035
        local UPDATE_STEP = 1 / 40

        local enabled  = false
        local tracked  = setmetatable({}, { __mode = "k" })
        local watchers = setmetatable({}, { __mode = "k" })
        local unregister

        local function classify(d)
            if d:IsA("MeshPart") then
                return { obj = d, kind = "part", props = { "Color", "Material", "TextureID" }, clearTexture = "TextureID" }
            elseif d:IsA("BasePart") then
                return { obj = d, kind = "part", props = { "Color", "Material" } }
            elseif d:IsA("SurfaceAppearance") then
                return { obj = d, kind = "surface", props = { "Parent" } }
            elseif d:IsA("Decal") or d:IsA("Texture") then
                return { obj = d, kind = "decal", props = {} }
            elseif d:IsA("SpecialMesh") then
                return { obj = d, kind = "vector", prop = "VertexColor", props = { "VertexColor", "TextureId" }, clearTexture = "TextureId" }
            elseif d:IsA("ParticleEmitter") or d:IsA("Beam") or d:IsA("Trail") then
                return { obj = d, kind = "sequence", prop = "Color", props = { "Color" } }
            elseif d:IsA("PointLight") or d:IsA("SpotLight") or d:IsA("SurfaceLight") then
                return { obj = d, kind = "color", prop = "Color", props = { "Color" } }
            elseif d:IsA("Highlight") then
                return { obj = d, kind = "color", prop = "FillColor", props = { "FillColor" } }
            end
            return nil
        end

        local function snapshot(node)
            node.original = {}
            for _, prop in ipairs(node.props) do
                local ok, val = pcall(function() return node.obj[prop] end)
                if ok then node.original[prop] = val end
            end
        end

        local function restoreNode(node)
            if node.kind == "decal" then CT_Trans.release(node.obj, "rainbow") end
            if not node.original then return end
            for prop, val in pairs(node.original) do
                pcall(function() node.obj[prop] = val end)
            end
        end

        local function applyOnce(node)
            if node.kind == "surface" then
                pcall(function() node.obj.Parent = nil end)
            elseif node.kind == "decal" then
                CT_Trans.claim(node.obj, "rainbow", 1)
            elseif node.clearTexture then
                pcall(function() node.obj[node.clearTexture] = "" end)
            end
        end

        local function addNode(entry, d)
            local node = classify(d)
            if not node then return end
            snapshot(node)
            applyOnce(node)
            if node.kind == "part" then
                table.insert(entry.parts, node)
            elseif node.kind == "surface" or node.kind == "decal" then
                table.insert(entry.statics, node)
            else
                table.insert(entry.effects, node)
            end
        end

        local function register(root)
            if tracked[root] then return end
            local entry = { parts = {}, effects = {}, statics = {}, conns = {} }
            tracked[root] = entry

            for _, d in ipairs(root:GetDescendants()) do addNode(entry, d) end
            if root:IsA("BasePart") then addNode(entry, root) end

            table.insert(entry.conns, root.DescendantAdded:Connect(function(d)
                addNode(entry, d)
            end))
            table.insert(entry.conns, root.AncestryChanged:Connect(function(_, parent)
                if not parent then unregister(root, false) end
            end))
        end

        function unregister(root, doRestore)
            local entry = tracked[root]
            if not entry then return end
            for _, conn in ipairs(entry.conns) do pcall(function() conn:Disconnect() end) end
            if doRestore then
                for _, node in ipairs(entry.parts)   do restoreNode(node) end
                for _, node in ipairs(entry.effects) do restoreNode(node) end
                for _, node in ipairs(entry.statics) do restoreNode(node) end
            end
            tracked[root] = nil
        end

        local function tryRegister(inst)
            if not enabled then return end
            if ctMatchItem(inst) then register(inst) end
        end

        local function unwatch(container)
            local conns = watchers[container]
            if not conns then return end
            for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
            watchers[container] = nil
        end

        local function watch(container)
            if not container or watchers[container] then return end
            watchers[container] = { container.ChildAdded:Connect(tryRegister) }
            for _, child in ipairs(container:GetChildren()) do tryRegister(child) end
        end

        local function watchAll()
            watch(_LP:FindFirstChildOfClass("Backpack"))
            watch(_LP.Character)
        end

        _LP.ChildAdded:Connect(function(child)
            if enabled and child:IsA("Backpack") then watch(child) end
        end)

        _LP.CharacterAdded:Connect(function(char)
            for root in pairs(tracked) do unregister(root, false) end
            for container in pairs(watchers) do unwatch(container) end
            if not enabled then return end
            watch(char)
            task.defer(function()
                if enabled then watchAll() end
            end)
        end)

        local acc = 0
        _RunService.Heartbeat:Connect(function(dt)
            if not enabled then return end
            if next(tracked) == nil then return end
            acc = acc + dt
            if acc < UPDATE_STEP then return end
            acc = 0

            local baseHue = (tick() * SPEED) % 1

            for _, entry in pairs(tracked) do
                for i, node in ipairs(entry.parts) do
                    local part = node.obj
                    if part.Parent then
                        pcall(function()
                            part.Color = Color3.fromHSV((baseHue + (i - 1) * SPREAD) % 1, 1, 1)
                        end)
                    end
                end
                for i, node in ipairs(entry.effects) do
                    if node.obj.Parent then
                        local col = Color3.fromHSV((baseHue + (i - 1) * SPREAD) % 1, 1, 1)
                        if node.kind == "sequence" then
                            pcall(function() node.obj[node.prop] = ColorSequence.new(col) end)
                        elseif node.kind == "vector" then
                            pcall(function() node.obj[node.prop] = Vector3.new(col.R, col.G, col.B) end)
                        else
                            pcall(function() node.obj[node.prop] = col end)
                        end
                    end
                end
            end
        end)

        table.insert(CT_JANITORS, function()
            for root in pairs(tracked) do
                if not root.Parent then unregister(root, false) end
            end
            for container in pairs(watchers) do
                if container ~= workspace and not container.Parent then unwatch(container) end
            end
        end)

        _G.AmbitiousRainbowTools = {
            setEnabled = function(on)
                on = on and true or false
                enabled = on
                _G.AmbitiousRainbowToolsEnabled = on
                if on then
                    watchAll()
                else
                    for root in pairs(tracked) do unregister(root, true) end
                    for container in pairs(watchers) do unwatch(container) end
                end
            end,
            isEnabled = function() return enabled end,
        }
    end

    -- ############################################################
    -- ##      CUSTOM TOOLS (BAT ONLY: DIAMOND SWORD & KATANA)   ##
    -- ############################################################
    do
        local ASSETS = {
            DiamondSword = {
                cat = "Bat",
                label = "Diamond Sword",
                mesh = "rbxassetid://8827558932",
                tex  = "rbxassetid://8827558969",
                scale = Vector3.new(0.2, 0.2, 0.2),
                c0 = CFrame.new(-0.05, -0.1, -0.12) * CFrame.Angles(math.rad(90), math.rad(180), 300),
                view = 4.9,
            },
            Katana = {
                cat = "Bat",
                label = "Katana",
                mesh = "rbxassetid://13528902482",
                tex  = "rbxassetid://13528902373",
                scale = Vector3.new(1.4, 1.4, 1.4),
                c0 = CFrame.new(0, 0.6, 0) * CFrame.Angles(math.rad(270), math.rad(180), math.rad(180)),
                view = 6.6,
            },
        }
        _G.AmbitiousCustomToolAssets = ASSETS
        _G.AmbitiousCustomToolSkins = _G.AmbitiousCustomToolSkins or { Bat = "DiamondSword" }

        local function skinForBat()
            local key = _G.AmbitiousCustomToolSkins and _G.AmbitiousCustomToolSkins.Bat
            if key and ASSETS[key] then return key end
            return "DiamondSword"
        end

        local enabled       = false
        local tracked       = setmetatable({}, { __mode = "k" })
        local watchers      = setmetatable({}, { __mode = "k" })
        local pendingHandle = setmetatable({}, { __mode = "k" })
        local teardown

        local function buildReplica(handle, mode)
            local existing = handle:FindFirstChild("LocalReplica")
            if existing then existing:Destroy() end

            local data = ASSETS[mode] or ASSETS.DiamondSword

            local m = Instance.new("Model")
            m.Name = "LocalReplica"

            local p = Instance.new("Part")
            p.Name         = "MainPart"
            p.CanCollide   = false
            p.CanQuery     = false
            p.CanTouch     = false
            p.Massless     = true
            p.Size         = Vector3.new(1, 1, 1)
            p.Transparency = 0
            p.Anchored     = false
            p.Parent       = m

            local mesh = Instance.new("SpecialMesh")
            mesh.MeshType  = Enum.MeshType.FileMesh
            mesh.MeshId    = data.mesh
            mesh.TextureId = data.tex
            mesh.Scale     = data.scale
            mesh.Parent    = p

            local w = Instance.new("Motor6D")
            w.Part0 = handle
            w.Part1 = p
            w.C0    = data.c0
            w.Parent = p

            m.Parent = handle
            return m
        end

        local function hideNode(entry, d)
            if isReplicaStuff(d) then return end
            if d:IsA("BasePart") or d:IsA("Decal") or d:IsA("Texture") then
                entry.hidden[d] = true
                CT_Trans.claim(d, "custom", 1)
            end
        end

        local function setupTool(tool)
            if tracked[tool] then return end

            local handle = tool:FindFirstChild("Handle")
            if not handle then
                if pendingHandle[tool] then return end
                local c
                c = tool.ChildAdded:Connect(function(child)
                    if child.Name == "Handle" then
                        pcall(function() c:Disconnect() end)
                        pendingHandle[tool] = nil
                        if enabled then setupTool(tool) end
                    end
                end)
                pendingHandle[tool] = c
                return
            end

            local entry = { hidden = {}, conns = {}, cat = "Bat" }
            tracked[tool] = entry

            for _, d in ipairs(tool:GetDescendants()) do hideNode(entry, d) end

            buildReplica(handle, skinForBat())

            table.insert(entry.conns, tool.DescendantAdded:Connect(function(d)
                task.defer(function()
                    if tracked[tool] then hideNode(entry, d) end
                end)
            end))
            table.insert(entry.conns, tool.AncestryChanged:Connect(function(_, parent)
                if not parent then teardown(tool, false) end
            end))
        end

        function teardown(tool, doRestore)
            local entry = tracked[tool]
            if not entry then return end
            for _, conn in ipairs(entry.conns) do pcall(function() conn:Disconnect() end) end

            local handle = tool:FindFirstChild("Handle")
            if handle then
                local rep = handle:FindFirstChild("LocalReplica")
                if rep then pcall(function() rep:Destroy() end) end
            end

            for obj in pairs(entry.hidden) do
                CT_Trans.release(obj, "custom")
            end
            entry.hidden = {}
            tracked[tool] = nil
        end

        local function tryRegister(inst)
            if not enabled then return end
            if inst:IsA("Tool") and ctMatchBatOnly(inst) then
                setupTool(inst)
            end
        end

        local function unwatch(container)
            local conns = watchers[container]
            if not conns then return end
            for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
            watchers[container] = nil
        end

        local function watch(container)
            if not container or watchers[container] then return end
            watchers[container] = { container.ChildAdded:Connect(tryRegister) }
            for _, child in ipairs(container:GetChildren()) do tryRegister(child) end
        end

        local function watchAll()
            watch(_LP:FindFirstChildOfClass("Backpack"))
            watch(_LP.Character)
        end

        _LP.ChildAdded:Connect(function(child)
            if enabled and child:IsA("Backpack") then watch(child) end
        end)

        _LP.CharacterAdded:Connect(function(char)
            for tool in pairs(tracked) do teardown(tool, false) end
            for _, c in pairs(pendingHandle) do pcall(function() c:Disconnect() end) end
            table.clear(pendingHandle)
            for container in pairs(watchers) do unwatch(container) end
            if not enabled then return end
            watch(char)
            task.defer(function()
                if enabled then watchAll() end
            end)
        end)

        table.insert(CT_JANITORS, function()
            for tool in pairs(tracked) do
                if not tool.Parent then teardown(tool, false) end
            end
            for tool, c in pairs(pendingHandle) do
                if not tool.Parent then
                    pcall(function() c:Disconnect() end)
                    pendingHandle[tool] = nil
                end
            end
            for container in pairs(watchers) do
                if not container.Parent then unwatch(container) end
            end
        end)

        local function rebuildIfNeeded(tool, entry, deep)
            local handle = tool:FindFirstChild("Handle")
            if not handle then return end
            local rep      = handle:FindFirstChild("LocalReplica")
            local mainPart = rep and rep:FindFirstChild("MainPart")
            local motor    = mainPart and mainPart:FindFirstChildOfClass("Motor6D")
            local broken   = (not rep) or (not mainPart) or (not motor) or motor.Part0 ~= handle
            if broken then
                buildReplica(handle, skinForBat())
            end
            if broken or deep then
                for _, d in ipairs(tool:GetDescendants()) do hideNode(entry, d) end
            end
        end

        local function integrityPass(deep)
            if not enabled then return end
            watchAll()
            local bp = _LP:FindFirstChildOfClass("Backpack")
            if bp then for _, ch in ipairs(bp:GetChildren()) do tryRegister(ch) end end
            local chr = _LP.Character
            if chr then for _, ch in ipairs(chr:GetChildren()) do tryRegister(ch) end end
            for tool, entry in pairs(tracked) do
                if not tool.Parent then
                    teardown(tool, false)
                else
                    rebuildIfNeeded(tool, entry, deep)
                end
            end
        end

        _G.AmbitiousSetCustomToolSkin = function(cat, key)
            if cat ~= "Bat" or not ASSETS[key] then return end
            _G.AmbitiousCustomToolSkins.Bat = key
            for tool, entry in pairs(tracked) do
                if tool.Parent and entry.cat == "Bat" then
                    local handle = tool:FindFirstChild("Handle")
                    if handle then pcall(buildReplica, handle, key) end
                end
            end
        end

        task.spawn(function()
            local n = 0
            while true do
                task.wait(0.4)
                if enabled then
                    n = n + 1
                    pcall(integrityPass, (n % 5) == 0)
                end
            end
        end)

        _LP.CharacterAdded:Connect(function()
            task.delay(0.6, function() if enabled then pcall(integrityPass, true) end end)
        end)

        _G.AmbitiousCustomTools = {
            setEnabled = function(on)
                on = on and true or false
                enabled = on
                _G.AmbitiousCustomToolsEnabled = on
                if on then
                    watchAll()
                    pcall(integrityPass, true)
                else
                    for tool in pairs(tracked) do teardown(tool, true) end
                    for _, c in pairs(pendingHandle) do pcall(function() c:Disconnect() end) end
                    table.clear(pendingHandle)
                    for container in pairs(watchers) do unwatch(container) end
                end
            end,
            isEnabled = function() return enabled end,
        }
    end

    -- ############################################################
    -- ##                    CUSTOM SOUNDS                       ##
    -- ############################################################
    do
        local SOUNDS = {
            Bat    = { id = "rbxassetid://5713085119", skip = 0.2 },
        }

        local hooked = setmetatable({}, { __mode = "k" })
        local enabled       = false
        local tracked       = setmetatable({}, { __mode = "k" })
        local watchers      = setmetatable({}, { __mode = "k" })
        local pendingHandle = setmetatable({}, { __mode = "k" })
        local teardown

        local function playCustom(entry)
            local cs = entry.sound
            if not cs or not cs.Parent then return end
            local d = entry.data

            if entry.timer then
                pcall(task.cancel, entry.timer)
                entry.timer = nil
            end

            pcall(function()
                cs:Stop()
                cs.TimePosition = d.skip or 0
                cs.Volume = 1
                cs:Play()
            end)

            if d.doublePlay and d.delay then
                entry.timer = task.delay(d.delay, function()
                    entry.timer = nil
                    if not enabled then return end
                    if cs and cs.Parent then
                        pcall(function()
                            cs:Stop()
                            cs.TimePosition = d.skip or 0
                            cs.Volume = 1
                            cs:Play()
                        end)
                    end
                end)
            end
        end

        local function hookSound(entry, snd)
            if not snd:IsA("Sound") then return end
            if snd.Name == "CustomSound" then return end
            if hooked[snd] then return end
            if entry.muted[snd] ~= nil then return end

            entry.muted[snd] = snd.Volume
            hooked[snd] = true

            local function trigger()
                if not enabled then return end
                if snd.Playing or snd.TimePosition > 0 then
                    pcall(function()
                        snd.Volume = 0
                        snd:Stop()
                    end)
                    playCustom(entry)
                end
            end

            local c1 = snd:GetPropertyChangedSignal("Playing"):Connect(trigger)
            local c2 = snd:GetPropertyChangedSignal("TimePosition"):Connect(trigger)
            table.insert(entry.conns, c1)
            table.insert(entry.conns, c2)

            local c3
            c3 = snd.AncestryChanged:Connect(function(_, parent)
                if parent then return end
                pcall(function() c1:Disconnect() end)
                pcall(function() c2:Disconnect() end)
                pcall(function() c3:Disconnect() end)
                hooked[snd] = nil
                entry.muted[snd] = nil
                if entry.timer then
                    pcall(task.cancel, entry.timer)
                    entry.timer = nil
                end
            end)
            table.insert(entry.conns, c3)

            if snd.Playing then trigger() end
        end

        local function setupTool(tool)
            if tracked[tool] then return end

            local item = ctMatchItem(tool)
            if not item then return end
            local data = SOUNDS[item.key]
            if not data then return end

            local handle = tool:FindFirstChild("Handle")
            if not handle then
                if pendingHandle[tool] then return end
                local c
                c = tool.ChildAdded:Connect(function(child)
                    if child.Name == "Handle" then
                        pcall(function() c:Disconnect() end)
                        pendingHandle[tool] = nil
                        if enabled then setupTool(tool) end
                    end
                end)
                pendingHandle[tool] = c
                return
            end

            local old = handle:FindFirstChild("CustomSound")
            if old then pcall(function() old:Destroy() end) end

            local cs = Instance.new("Sound")
            cs.Name        = "CustomSound"
            cs.SoundId     = data.id
            cs.Volume      = 1
            cs.Looped      = false
            cs.RollOffMode = Enum.RollOffMode.Inverse
            cs.MaxDistance = 1000
            cs.MinDistance = 1000
            cs.Parent      = handle

            local entry = { sound = cs, data = data, conns = {}, muted = {} }
            tracked[tool] = entry

            for _, d in ipairs(tool:GetDescendants()) do hookSound(entry, d) end

            table.insert(entry.conns, tool.DescendantAdded:Connect(function(d)
                if tracked[tool] then hookSound(entry, d) end
            end))
            table.insert(entry.conns, tool.AncestryChanged:Connect(function(_, parent)
                if not parent then teardown(tool) end
            end))
        end

        function teardown(tool)
            local entry = tracked[tool]
            if not entry then return end
            if entry.timer then
                pcall(task.cancel, entry.timer)
                entry.timer = nil
            end
            for _, conn in ipairs(entry.conns) do pcall(function() conn:Disconnect() end) end
            if entry.sound then pcall(function() entry.sound:Destroy() end) end
            for snd, vol in pairs(entry.muted) do
                hooked[snd] = nil
                if snd and snd.Parent then pcall(function() snd.Volume = vol end) end
            end
            tracked[tool] = nil
        end

        local function tryRegister(inst)
            if not enabled then return end
            if inst:IsA("Tool") and ctMatchItem(inst) then setupTool(inst) end
        end

        local function unwatch(container)
            local conns = watchers[container]
            if not conns then return end
            for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
            watchers[container] = nil
        end

        local function watch(container)
            if not container or watchers[container] then return end
            watchers[container] = { container.ChildAdded:Connect(tryRegister) }
            for _, child in ipairs(container:GetChildren()) do tryRegister(child) end
        end

        local function watchAll()
            watch(_LP:FindFirstChildOfClass("Backpack"))
            watch(_LP.Character)
        end

        _LP.ChildAdded:Connect(function(child)
            if enabled and child:IsA("Backpack") then watch(child) end
        end)

        _LP.CharacterAdded:Connect(function(char)
            for tool in pairs(tracked) do teardown(tool) end
            for _, c in pairs(pendingHandle) do pcall(function() c:Disconnect() end) end
            table.clear(pendingHandle)
            for container in pairs(watchers) do unwatch(container) end
            if not enabled then return end
            watch(char)
            task.defer(function()
                if enabled then watchAll() end
            end)
        end)

        table.insert(CT_JANITORS, function()
            for tool in pairs(tracked) do
                if not tool.Parent then teardown(tool) end
            end
            for tool, c in pairs(pendingHandle) do
                if not tool.Parent then
                    pcall(function() c:Disconnect() end)
                    pendingHandle[tool] = nil
                end
            end
            for container in pairs(watchers) do
                if not container.Parent then unwatch(container) end
            end
        end)

        _G.AmbitiousCustomSounds = {
            setEnabled = function(on)
                on = on and true or false
                enabled = on
                _G.AmbitiousCustomSoundsEnabled = on
                if on then
                    watchAll()
                else
                    for tool in pairs(tracked) do teardown(tool) end
                    for _, c in pairs(pendingHandle) do pcall(function() c:Disconnect() end) end
                    table.clear(pendingHandle)
                    for container in pairs(watchers) do unwatch(container) end
                end
            end,
            isEnabled = function() return enabled end,
        }
    end
end

-- ============================================================
-- AMBITIOUS HUB BAT COUNTER (V1 & V2)
-- ============================================================
do
    local Players = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local LP = Players.LocalPlayer

    local batCounterEnabled = false
    local batCounterMode = _G._AdaptBatCounterMode or "V1"
    local batConn = nil
    local batDebounce = false
    local enemyLock = {}
    local watchConns = {}
    local RAGDOLL_LOCK_SECONDS = 2.6

    local SLAP_LIST = {
        "Bat", "Slap", "Iron Slap", "Gold Slap", "Diamond Slap", "Emerald Slap",
        "Ruby Slap", "Dark Matter Slap", "Flame Slap", "Nuclear Slap", "Galaxy Slap", "Glitched Slap"
    }

    local function findBatForCounter()
        local c = LP.Character
        if not c then return nil end
        local bp = LP:FindFirstChildOfClass("Backpack") or LP:FindFirstChild("Backpack")
        for _, name in ipairs(SLAP_LIST) do
            local t = c:FindFirstChild(name) or (bp and bp:FindFirstChild(name))
            if t then return t end
        end
        for _, ch in ipairs(c:GetChildren()) do
            if ch:IsA("Tool") and ch.Name:lower():find("bat") then return ch end
        end
        if bp then
            for _, ch in ipairs(bp:GetChildren()) do
                if ch:IsA("Tool") and ch.Name:lower():find("bat") then return ch end
            end
        end
        return nil
    end

    local function swingBatForCounter(bat, char)
        if not bat or not char then return end
        local hum = char:FindFirstChildOfClass("Humanoid")
        if bat.Parent ~= char then
            if hum then pcall(function() hum:EquipTool(bat) end) end
            task.wait(0.05)
        end
        local remote = bat:FindFirstChildOfClass("RemoteEvent") or bat:FindFirstChildOfClass("RemoteFunction")
        if remote and remote:IsA("RemoteEvent") then
            pcall(function() remote:FireServer() end)
            task.wait(0.15)
            pcall(function() remote:FireServer() end)
        else
            pcall(function() bat:Activate() end)
            task.wait(0.15)
            pcall(function() bat:Activate() end)
        end
    end

    local function isRagdollForBat(hum)
        if not hum then return false end
        local st = hum:GetState()
        return st == Enum.HumanoidStateType.Physics
            or st == Enum.HumanoidStateType.Ragdoll
            or hum.PlatformStand == true
    end

    local function stopEnemyRagdollWatcher()
        for k, c in pairs(watchConns) do
            pcall(function() c:Disconnect() end)
            watchConns[k] = nil
        end
        for k in pairs(enemyLock) do
            enemyLock[k] = nil
        end
    end

    local function startEnemyRagdollWatcher()
        stopEnemyRagdollWatcher()
        local function hookChar(plr, char)
            if not char then return end
            local key = tostring(plr.UserId) .. "_char"
            if watchConns[key] then pcall(function() watchConns[key]:Disconnect() end) end
            watchConns[key] = char.DescendantAdded:Connect(function(d)
                if d:IsA("BallSocketConstraint") then
                    enemyLock[plr] = tick() + RAGDOLL_LOCK_SECONDS
                end
            end)
        end
        local function watchPlayer(plr)
            if plr == LP then return end
            local key = tostring(plr.UserId) .. "_added"
            if watchConns[key] then pcall(function() watchConns[key]:Disconnect() end) end
            watchConns[key] = plr.CharacterAdded:Connect(function(char)
                hookChar(plr, char)
            end)
            if plr.Character then hookChar(plr, plr.Character) end
        end
        watchConns["_playerAdded"] = Players.PlayerAdded:Connect(watchPlayer)
        watchConns["_playerRemoving"] = Players.PlayerRemoving:Connect(function(plr)
            enemyLock[plr] = nil
            local ka = tostring(plr.UserId) .. "_added"
            local kc = tostring(plr.UserId) .. "_char"
            if watchConns[ka] then pcall(function() watchConns[ka]:Disconnect() end) watchConns[ka] = nil end
            if watchConns[kc] then pcall(function() watchConns[kc]:Disconnect() end) watchConns[kc] = nil end
        end)
        for _, plr in ipairs(Players:GetPlayers()) do
            watchPlayer(plr)
        end
    end

    local function getNearestEnemy()
        local char = LP.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return nil end
        local myPos = hrp.Position
        local best, bestDist = nil, math.huge
        for _, plr in ipairs(Players:GetPlayers()) do
            if plr ~= LP then
                local ec = plr.Character
                local ehrp = ec and ec:FindFirstChild("HumanoidRootPart")
                local ehum = ec and ec:FindFirstChildOfClass("Humanoid")
                if ehrp and ehum and ehum.Health > 0 then
                    local d = (ehrp.Position - myPos).Magnitude
                    if d < bestDist then
                        bestDist = d
                        best = plr
                    end
                end
            end
        end
        return best
    end

    local function isNearestEnemyRagdolled()
        local plr = getNearestEnemy()
        if not plr then return false end
        local lockUntil = enemyLock[plr]
        return lockUntil ~= nil and lockUntil > tick()
    end

    local function stopBatCounter()
        if batConn then
            batConn:Disconnect()
            batConn = nil
        end
        batDebounce = false
        stopEnemyRagdollWatcher()
    end

    local function startBatCounter()
        if batConn then return end
        batDebounce = false
        startEnemyRagdollWatcher()
        batConn = RunService.Heartbeat:Connect(function()
            if not batCounterEnabled or batDebounce then return end
            local char = LP.Character
            if not char then return end
            local hum = char:FindFirstChildOfClass("Humanoid")
            if not hum or hum.Health <= 0 then return end
            if _G._SoloNTXAInstantResetBusy then return end

            if isRagdollForBat(hum) then
                batDebounce = true
                if batCounterMode == "V2" then
                    if isNearestEnemyRagdolled() then
                        task.spawn(function()
                            local t0 = tick()
                            while tick() - t0 < 10 do
                                local c2 = LP.Character
                                local h2 = c2 and c2:FindFirstChildOfClass("Humanoid")
                                if not h2 or not isRagdollForBat(h2) then break end
                                task.wait(0.1)
                            end
                            task.wait(0.2)
                            batDebounce = false
                        end)
                        return
                    end
                    -- V2: save CFrame, snap to nearest enemy for 0.4s + swing, then restore CFrame
                    task.spawn(function()
                        task.wait(0.05)
                        local wasTPBatOn = (_G._AdaptSnowTPBatEnabled == true)
                        local hrpNow = char and char:FindFirstChild("HumanoidRootPart")
                        local savedCF = hrpNow and hrpNow.CFrame or nil
                        if not wasTPBatOn and _G._AdaptSnowTPBatSetEnabled then
                            pcall(_G._AdaptSnowTPBatSetEnabled, true)
                        end
                        local bat = findBatForCounter()
                        if bat then task.spawn(function() swingBatForCounter(bat, char) end) end

                        local snapConn
                        snapConn = RunService.Heartbeat:Connect(function()
                            local c2 = LP.Character
                            local h2 = c2 and c2:FindFirstChild("HumanoidRootPart")
                            local hum2 = c2 and c2:FindFirstChildOfClass("Humanoid")
                            if not h2 or not hum2 or hum2.Health <= 0 then return end
                            local t2 = getNearestEnemy()
                            local tc2 = t2 and t2.Character
                            local tr2 = tc2 and tc2:FindFirstChild("HumanoidRootPart")
                            if not tr2 then return end
                            local targetPos = tr2.Position
                            if _G.AdaptNTXAAntiVoid and _G.AdaptNTXAAntiVoid.posForPart then
                                targetPos = _G.AdaptNTXAAntiVoid.posForPart(tr2, targetPos)
                            end
                            pcall(function()
                                h2.CFrame = CFrame.new(targetPos + Vector3.new(0, 0.9, 0))
                                h2.AssemblyLinearVelocity = Vector3.zero
                                h2.AssemblyAngularVelocity = Vector3.zero
                            end)
                        end)

                        task.wait(0.4)
                        if snapConn then pcall(function() snapConn:Disconnect() end) snapConn = nil end
                        if not wasTPBatOn and _G._AdaptSnowTPBatSetEnabled then
                            pcall(_G._AdaptSnowTPBatSetEnabled, false)
                        end
                        if savedCF then
                            local hrpBack = char and char:FindFirstChild("HumanoidRootPart")
                            if hrpBack then
                                pcall(function()
                                    hrpBack.CFrame = savedCF
                                    hrpBack.AssemblyLinearVelocity = Vector3.zero
                                end)
                            end
                        end
                        task.wait(0.5)
                        batDebounce = false
                    end)
                else
                    -- V1: LookAt + swing bat together for 0.7s, then restore LookAt
                    task.spawn(function()
                        local wasLookAt = (_G._AdaptLookAtEnemyEnabled == true)
                        local savedRadius = _G._AdaptLookAtEnemyRadius or 20
                        _G._AdaptLookAtEnemyRadius = math.huge
                        if _G._AdaptLookAtEnemy and _G._AdaptLookAtEnemy.SetEnabled then
                            pcall(_G._AdaptLookAtEnemy.SetEnabled, true)
                        end
                        local bat = findBatForCounter()
                        if bat then task.spawn(function() swingBatForCounter(bat, char) end) end
                        task.wait(0.7)
                        _G._AdaptLookAtEnemyRadius = savedRadius
                        if _G._AdaptLookAtEnemy and _G._AdaptLookAtEnemy.SetEnabled then
                            pcall(_G._AdaptLookAtEnemy.SetEnabled, wasLookAt)
                        end
                        task.wait(0.5)
                        batDebounce = false
                    end)
                end
            end
        end)
    end

    _G.AmbitiousSetBatCounterEnabled = function(on)
        batCounterEnabled = (on == true)
        if _G._AdaptOshaBatCounter and _G._AdaptOshaBatCounter.stop then
            pcall(_G._AdaptOshaBatCounter.stop)
            _G._AdaptOshaBatCounter.on = false
        end
        if batCounterEnabled then
            startBatCounter()
        else
            stopBatCounter()
        end
    end

    _G.AmbitiousSetBatCounterMode = function(mode)
        batCounterMode = (mode == "V2") and "V2" or "V1"
    end

    if _G._VezyBatCounterOn then
        batCounterMode = (_G._AdaptBatCounterMode == "V2") and "V2" or "V1"
        _G.AmbitiousSetBatCounterEnabled(true)
    end
end

-- Sync late-initialized modules (Defenses, Custom Tools, Rainbow Tools, Custom Sounds, Bat Aimbot V5)
task.spawn(function()
    if _G._AdaptApplySavedDefenses then pcall(_G._AdaptApplySavedDefenses) end
    if _G.AmbitiousSetCustomToolSkin then
        pcall(_G.AmbitiousSetCustomToolSkin, "Bat", (_G.AmbitiousCustomToolSkins and _G.AmbitiousCustomToolSkins.Bat) or "DiamondSword")
    end
    if _G.AmbitiousCustomTools then
        pcall(_G.AmbitiousCustomTools.setEnabled, _G.AmbitiousCustomToolsEnabled ~= false)
    end
    if _G.AmbitiousRainbowTools then
        pcall(_G.AmbitiousRainbowTools.setEnabled, _G.AmbitiousRainbowToolsEnabled ~= false)
    end
    if _G.AmbitiousCustomSounds then
        pcall(_G.AmbitiousCustomSounds.setEnabled, _G.AmbitiousCustomSoundsEnabled ~= false)
    end
    if _G._AdaptUnifiedAimbotConfigure then
        pcall(_G._AdaptUnifiedAimbotConfigure, _G._AdaptSavedAimbotVersion or "V5", _G._AdaptSavedAimbotMode or "NORMAL", _G._loadedOn_batAimbot == true)
    end
end)


-- ============================================================
-- SOLO ON-SCREEN INPUT OVERLAYS: CONTROLLER HUD & KEYBOARD/MOUSE HUD
-- ============================================================
do
    local Players = game:GetService("Players")
    local UserInputService = game:GetService("UserInputService")
    local TweenService = game:GetService("TweenService")
    local CoreGui = game:GetService("CoreGui")
    local LP = Players.LocalPlayer

    if _G._SoloInputHudGui and _G._SoloInputHudGui.Parent then
        pcall(function() _G._SoloInputHudGui:Destroy() end)
    end

    local guiParent = (type(gethui) == "function" and gethui()) or CoreGui or (LP and LP:FindFirstChildOfClass("PlayerGui"))
    local hudGui = Instance.new("ScreenGui")
    hudGui.Name = "SoloInputOverlayGui"
    hudGui.ResetOnSpawn = false
    hudGui.IgnoreGuiInset = true
    hudGui.DisplayOrder = 940
    hudGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    pcall(function() hudGui.Parent = guiParent end)
    if not hudGui.Parent and LP then
        pcall(function() hudGui.Parent = LP:WaitForChild("PlayerGui", 2) end)
    end
    _G._SoloInputHudGui = hudGui

    local COLOR_BG       = Color3.fromRGB(8, 8, 12)
    local COLOR_KEY_IDLE = Color3.fromRGB(16, 16, 22)
    local COLOR_KEY_ON   = Color3.fromRGB(220, 20, 42)
    local COLOR_TEXT_IDLE= Color3.fromRGB(225, 228, 235)
    local COLOR_TEXT_ON  = Color3.fromRGB(255, 255, 255)
    local COLOR_STROKE   = Color3.fromRGB(185, 22, 42)
    local COLOR_STROKE_ON= Color3.fromRGB(255, 210, 220)

    local function makeDraggable(frame, saveKey)
        local dragging = false
        local dragInput = nil
        local dragStart = nil
        local startPos = nil

        frame.Active = true
        frame.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragging = true
                dragStart = input.Position
                startPos = frame.Position
                dragInput = input
                input.Changed:Connect(function()
                    if input.UserInputState == Enum.UserInputState.End then
                        if dragging then
                            dragging = false
                            local p = frame.Position
                            _G[saveKey] = { xs = p.X.Scale, xo = p.X.Offset, ys = p.Y.Scale, yo = p.Y.Offset }
                            if _G._AdaptRequestSave then
                                task.spawn(function() pcall(_G._AdaptRequestSave, true) end)
                            end
                        end
                    end
                end)
            end
        end)

        frame.InputChanged:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
                dragInput = input
            end
        end)

        UserInputService.InputChanged:Connect(function(input)
            if dragging and input == dragInput and dragStart and startPos then
                local delta = input.Position - dragStart
                frame.Position = UDim2.new(
                    startPos.X.Scale,
                    startPos.X.Offset + delta.X,
                    startPos.Y.Scale,
                    startPos.Y.Offset + delta.Y
                )
            end
        end)
    end

    local function createOverlayPanel(name, titleText, defaultPos, sizeW, sizeH, saveKey)
        local panel = Instance.new("Frame")
        panel.Name = name
        panel.Size = UDim2.fromOffset(sizeW, sizeH)
        panel.Position = defaultPos
        panel.BackgroundColor3 = COLOR_BG
        panel.BackgroundTransparency = 0.16
        panel.BorderSizePixel = 0
        panel.Visible = false
        panel.Parent = hudGui

        local scale = Instance.new("UIScale")
        scale.Scale = 0.94
        scale.Parent = panel

        local corner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(0, 12)
        corner.Parent = panel

        if _G._SoloApplyAnimatedOutline then
            pcall(_G._SoloApplyAnimatedOutline, panel, 2)
        else
            local st = Instance.new("UIStroke")
            st.Color = COLOR_STROKE
            st.Thickness = 1.6
            st.Transparency = 0.15
            st.Parent = panel
        end

        local header = Instance.new("TextLabel")
        header.Name = "HeaderTitle"
        header.BackgroundTransparency = 1
        header.Position = UDim2.fromOffset(10, 4)
        header.Size = UDim2.new(1, -52, 0, 14)
        header.Font = Enum.Font.GothamBlack
        header.Text = titleText
        header.TextSize = 9
        header.TextColor3 = Color3.fromRGB(255, 70, 90)
        header.TextXAlignment = Enum.TextXAlignment.Left
        header.Parent = panel

        local dragBadge = Instance.new("TextLabel")
        dragBadge.Name = "DragHint"
        dragBadge.BackgroundTransparency = 1
        dragBadge.Position = UDim2.new(1, -44, 0, 4)
        dragBadge.Size = UDim2.fromOffset(36, 14)
        dragBadge.Font = Enum.Font.GothamBold
        dragBadge.Text = "DRAG"
        dragBadge.TextSize = 8
        dragBadge.TextColor3 = Color3.fromRGB(140, 145, 160)
        dragBadge.TextXAlignment = Enum.TextXAlignment.Right
        dragBadge.Parent = panel

        makeDraggable(panel, saveKey)
        return panel
    end

    local function makeCap(parent, label, x, y, w, h, radius)
        local f = Instance.new("Frame")
        f.Name = "Cap_" .. label
        f.Position = UDim2.fromOffset(x, y)
        f.Size = UDim2.fromOffset(w, h)
        f.BackgroundColor3 = COLOR_KEY_IDLE
        f.BackgroundTransparency = 0.08
        f.BorderSizePixel = 0
        f.Parent = parent

        local c = Instance.new("UICorner")
        c.CornerRadius = UDim.new(0, radius or 6)
        c.Parent = f

        local st = Instance.new("UIStroke")
        st.Color = COLOR_STROKE
        st.Thickness = 1.15
        st.Transparency = 0.35
        st.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        st.Parent = f

        local t = Instance.new("TextLabel")
        t.Name = "Label"
        t.BackgroundTransparency = 1
        t.Size = UDim2.fromScale(1, 1)
        t.Font = Enum.Font.GothamBlack
        t.Text = label
        t.TextSize = (w <= 20 or #label >= 4) and 8 or 9
        t.TextColor3 = COLOR_TEXT_IDLE
        t.Parent = f

        local function setPressed(on)
            TweenService:Create(f, TweenInfo.new(0.06, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                BackgroundColor3 = on and COLOR_KEY_ON or COLOR_KEY_IDLE,
                BackgroundTransparency = on and 0 or 0.08,
            }):Play()
            TweenService:Create(st, TweenInfo.new(0.06), {
                Color = on and COLOR_STROKE_ON or COLOR_STROKE,
                Thickness = on and 1.8 or 1.15,
                Transparency = on and 0 or 0.35,
            }):Play()
            t.TextColor3 = on and COLOR_TEXT_ON or COLOR_TEXT_IDLE
        end

        return setPressed, f
    end

    -- ============================================================
    -- 1. CONTROLLER HUD (212 x 134)
    -- ============================================================
    local ctrlFrame = createOverlayPanel(
        "SoloControllerHUD",
        "CONTROLLER HUD",
        UDim2.new(0, 18, 1, -154),
        212,
        134,
        "_SoloControllerHudPos"
    )

    local ctrlMap = {}
    local function bindCtrl(keyCode, setter)
        ctrlMap[keyCode] = setter
    end

    -- Top Bumpers & Triggers
    bindCtrl(Enum.KeyCode.ButtonL2, makeCap(ctrlFrame, "LT", 10, 20, 36, 16, 5))
    bindCtrl(Enum.KeyCode.ButtonL1, makeCap(ctrlFrame, "LB", 50, 20, 36, 16, 5))
    bindCtrl(Enum.KeyCode.ButtonR1, makeCap(ctrlFrame, "RB", 126, 20, 36, 16, 5))
    bindCtrl(Enum.KeyCode.ButtonR2, makeCap(ctrlFrame, "RT", 166, 20, 36, 16, 5))

    -- Center Select / Start
    bindCtrl(Enum.KeyCode.ButtonSelect, makeCap(ctrlFrame, "SEL", 83, 44, 21, 14, 4))
    bindCtrl(Enum.KeyCode.ButtonStart,  makeCap(ctrlFrame, "STRT", 108, 44, 21, 14, 4))

    -- Left D-Pad Cross
    bindCtrl(Enum.KeyCode.DPadUp,    makeCap(ctrlFrame, "▲", 28, 42, 18, 18, 4))
    bindCtrl(Enum.KeyCode.DPadLeft,  makeCap(ctrlFrame, "◀", 10, 60, 18, 18, 4))
    bindCtrl(Enum.KeyCode.DPadRight, makeCap(ctrlFrame, "▶", 46, 60, 18, 18, 4))
    bindCtrl(Enum.KeyCode.DPadDown,  makeCap(ctrlFrame, "▼", 28, 78, 18, 18, 4))

    -- Right Face Buttons (Y, X, B, A Diamond)
    bindCtrl(Enum.KeyCode.ButtonY, makeCap(ctrlFrame, "Y", 166, 42, 18, 18, 9))
    bindCtrl(Enum.KeyCode.ButtonX, makeCap(ctrlFrame, "X", 148, 60, 18, 18, 9))
    bindCtrl(Enum.KeyCode.ButtonB, makeCap(ctrlFrame, "B", 184, 60, 18, 18, 9))
    bindCtrl(Enum.KeyCode.ButtonA, makeCap(ctrlFrame, "A", 166, 78, 18, 18, 9))

    -- Left & Right Analog Stick Wells (LS & RS)
    local function makeStickWell(label, wellX, wellY)
        local well = Instance.new("Frame")
        well.Name = "Well_" .. label
        well.Position = UDim2.fromOffset(wellX, wellY)
        well.Size = UDim2.fromOffset(38, 38)
        well.BackgroundColor3 = Color3.fromRGB(12, 12, 16)
        well.BackgroundTransparency = 0.1
        well.BorderSizePixel = 0
        well.Parent = ctrlFrame
        Instance.new("UICorner", well).CornerRadius = UDim.new(1, 0)

        local wst = Instance.new("UIStroke")
        wst.Color = COLOR_STROKE
        wst.Thickness = 1.2
        wst.Transparency = 0.35
        wst.Parent = well

        local nub = Instance.new("Frame")
        nub.Name = "Nub"
        nub.AnchorPoint = Vector2.new(0.5, 0.5)
        nub.Position = UDim2.new(0.5, 0, 0.5, 0)
        nub.Size = UDim2.fromOffset(20, 20)
        nub.BackgroundColor3 = COLOR_KEY_IDLE
        nub.BorderSizePixel = 0
        nub.Parent = well
        Instance.new("UICorner", nub).CornerRadius = UDim.new(1, 0)

        local nst = Instance.new("UIStroke")
        nst.Color = Color3.fromRGB(235, 45, 65)
        nst.Thickness = 1.2
        nst.Transparency = 0.2
        nst.Parent = nub

        local lbl = Instance.new("TextLabel")
        lbl.BackgroundTransparency = 1
        lbl.Size = UDim2.fromScale(1, 1)
        lbl.Font = Enum.Font.GothamBlack
        lbl.Text = label
        lbl.TextSize = 7
        lbl.TextColor3 = COLOR_TEXT_IDLE
        lbl.Parent = nub

        local clicked = false
        local moved = false
        local function refreshVisual()
            local active = clicked or moved
            nub.BackgroundColor3 = active and COLOR_KEY_ON or COLOR_KEY_IDLE
            nst.Color = active and COLOR_STROKE_ON or Color3.fromRGB(235, 45, 65)
            lbl.TextColor3 = active and COLOR_TEXT_ON or COLOR_TEXT_IDLE
        end

        local function setClick(on)
            clicked = on == true
            refreshVisual()
        end

        local function setAxis(vec)
            local dx = math.clamp(vec.X or 0, -1, 1)
            local dy = math.clamp(-(vec.Y or 0), -1, 1)
            moved = (math.abs(dx) > 0.12 or math.abs(dy) > 0.12)
            nub.Position = UDim2.new(0.5, math.floor(dx * 8 + 0.5), 0.5, math.floor(dy * 8 + 0.5))
            refreshVisual()
        end

        return setClick, setAxis
    end

    local setL3, setLS = makeStickWell("LS", 66, 88)
    local setR3, setRS = makeStickWell("RS", 108, 88)
    bindCtrl(Enum.KeyCode.ButtonL3, setL3)
    bindCtrl(Enum.KeyCode.ButtonR3, setR3)

    -- ============================================================
    -- 2. KEYBOARD & MOUSE HUD (230 x 134)
    -- ============================================================
    local kbmFrame = createOverlayPanel(
        "SoloKBMHUD",
        "KEYBOARD & MOUSE",
        UDim2.new(0, 238, 1, -154),
        230,
        134,
        "_SoloKbmHudPos"
    )

    local kbmKeyMap = {}
    local function bindKBM(keyCode, setter)
        if type(keyCode) == "table" then
            for _, k in ipairs(keyCode) do
                kbmKeyMap[k] = setter
            end
        else
            kbmKeyMap[keyCode] = setter
        end
    end

    -- Row 1: Q W E R
    bindKBM(Enum.KeyCode.Q, makeCap(kbmFrame, "Q", 10, 22, 24, 22, 5))
    bindKBM(Enum.KeyCode.W, makeCap(kbmFrame, "W", 37, 22, 24, 22, 5))
    bindKBM(Enum.KeyCode.E, makeCap(kbmFrame, "E", 64, 22, 24, 22, 5))
    bindKBM(Enum.KeyCode.R, makeCap(kbmFrame, "R", 91, 22, 24, 22, 5))

    -- Row 2: A S D F G
    bindKBM(Enum.KeyCode.A, makeCap(kbmFrame, "A", 10, 47, 24, 22, 5))
    bindKBM(Enum.KeyCode.S, makeCap(kbmFrame, "S", 37, 47, 24, 22, 5))
    bindKBM(Enum.KeyCode.D, makeCap(kbmFrame, "D", 64, 47, 24, 22, 5))
    bindKBM(Enum.KeyCode.F, makeCap(kbmFrame, "F", 91, 47, 24, 22, 5))
    bindKBM(Enum.KeyCode.G, makeCap(kbmFrame, "G", 118, 47, 24, 22, 5))

    -- Row 3: SHIFT Z X C V
    bindKBM({Enum.KeyCode.LeftShift, Enum.KeyCode.RightShift}, makeCap(kbmFrame, "SHFT", 10, 72, 30, 22, 5))
    bindKBM(Enum.KeyCode.Z, makeCap(kbmFrame, "Z", 43, 72, 22, 22, 5))
    bindKBM(Enum.KeyCode.X, makeCap(kbmFrame, "X", 68, 72, 22, 22, 5))
    bindKBM(Enum.KeyCode.C, makeCap(kbmFrame, "C", 93, 72, 22, 22, 5))
    bindKBM(Enum.KeyCode.V, makeCap(kbmFrame, "V", 118, 72, 24, 22, 5))

    -- Row 4: SPACE
    bindKBM(Enum.KeyCode.Space, makeCap(kbmFrame, "SPACE", 10, 98, 132, 24, 6))

    -- Mouse Diagram on Right Side (x = 150..220, y = 22..122)
    local mouseHousing = Instance.new("Frame")
    mouseHousing.Name = "MouseBody"
    mouseHousing.Position = UDim2.fromOffset(150, 22)
    mouseHousing.Size = UDim2.fromOffset(70, 100)
    mouseHousing.BackgroundColor3 = Color3.fromRGB(12, 12, 16)
    mouseHousing.BackgroundTransparency = 0.08
    mouseHousing.BorderSizePixel = 0
    mouseHousing.Parent = kbmFrame
    Instance.new("UICorner", mouseHousing).CornerRadius = UDim.new(0, 18)

    local mhStroke = Instance.new("UIStroke")
    mhStroke.Color = COLOR_STROKE
    mhStroke.Thickness = 1.25
    mhStroke.Transparency = 0.25
    mhStroke.Parent = mouseHousing

    local setLMB = makeCap(mouseHousing, "LMB", 4, 4, 27, 40, 8)
    local setMMB = makeCap(mouseHousing, "M",   32, 8, 6, 26, 3)
    local setRMB = makeCap(mouseHousing, "RMB", 39, 4, 27, 40, 8)

    local mousePalm = Instance.new("TextLabel")
    mousePalm.BackgroundTransparency = 1
    mousePalm.Position = UDim2.fromOffset(0, 50)
    mousePalm.Size = UDim2.new(1, 0, 0, 44)
    mousePalm.Font = Enum.Font.GothamBlack
    mousePalm.Text = "SOLO"
    mousePalm.TextSize = 9
    mousePalm.TextColor3 = Color3.fromRGB(185, 35, 55)
    mousePalm.Parent = mouseHousing

    -- ============================================================
    -- INPUT LISTENERS (REAL-TIME HIGHLIGHTING)
    -- ============================================================
    UserInputService.InputBegan:Connect(function(input)
        local kc = input.KeyCode
        if kc and kc ~= Enum.KeyCode.Unknown then
            if ctrlMap[kc] then pcall(ctrlMap[kc], true) end
            if kbmKeyMap[kc] then pcall(kbmKeyMap[kc], true) end
        end
        local ut = input.UserInputType
        if ut == Enum.UserInputType.MouseButton1 then
            pcall(setLMB, true)
        elseif ut == Enum.UserInputType.MouseButton2 then
            pcall(setRMB, true)
        elseif ut == Enum.UserInputType.MouseButton3 then
            pcall(setMMB, true)
        end
    end)

    UserInputService.InputEnded:Connect(function(input)
        local kc = input.KeyCode
        if kc and kc ~= Enum.KeyCode.Unknown then
            if ctrlMap[kc] then pcall(ctrlMap[kc], false) end
            if kbmKeyMap[kc] then pcall(kbmKeyMap[kc], false) end
        end
        local ut = input.UserInputType
        if ut == Enum.UserInputType.MouseButton1 then
            pcall(setLMB, false)
        elseif ut == Enum.UserInputType.MouseButton2 then
            pcall(setRMB, false)
        elseif ut == Enum.UserInputType.MouseButton3 then
            pcall(setMMB, false)
        end
    end)

    UserInputService.InputChanged:Connect(function(input)
        local kc = input.KeyCode
        if kc == Enum.KeyCode.Thumbstick1 then
            pcall(setLS, input.Position)
        elseif kc == Enum.KeyCode.Thumbstick2 then
            pcall(setRS, input.Position)
        elseif kc == Enum.KeyCode.ButtonL2 and ctrlMap[Enum.KeyCode.ButtonL2] then
            pcall(ctrlMap[Enum.KeyCode.ButtonL2], (input.Position and input.Position.Z or 0) > 0.15)
        elseif kc == Enum.KeyCode.ButtonR2 and ctrlMap[Enum.KeyCode.ButtonR2] then
            pcall(ctrlMap[Enum.KeyCode.ButtonR2], (input.Position and input.Position.Z or 0) > 0.15)
        end
    end)

    local function applySavedPositions()
        if type(_G._SoloControllerHudPos) == "table" and type(_G._SoloControllerHudPos.xs) == "number" then
            local p = _G._SoloControllerHudPos
            ctrlFrame.Position = UDim2.new(p.xs, p.xo or 0, p.ys, p.yo or 0)
        end
        if type(_G._SoloKbmHudPos) == "table" and type(_G._SoloKbmHudPos.xs) == "number" then
            local p = _G._SoloKbmHudPos
            kbmFrame.Position = UDim2.new(p.xs, p.xo or 0, p.ys, p.yo or 0)
        end
    end

    _G.SoloInputHUD = {
        SetControllerEnabled = function(on)
            _G._SoloControllerHudOn = (on == true)
            ctrlFrame.Visible = (on == true)
        end,
        SetKBMEnabled = function(on)
            _G._SoloKbmHudOn = (on == true)
            kbmFrame.Visible = (on == true)
        end,
        ApplySavedPositions = applySavedPositions,
    }

    applySavedPositions()
    ctrlFrame.Visible = (_G._SoloControllerHudOn == true)
    kbmFrame.Visible = (_G._SoloKbmHudOn == true)
end